programs.sol:
"""Negative lexical signal for social life and organizations.

'Social' and 社 are strongest; society-root fragments, translations,
communities and social-network names are weaker. The company ending 会社
and shrine ending 神社 are weaker than other uses of 社. One previous
token supplies these endings and the social media/security and society-of
phrase adjustments. Smaller unrelated responses are left unmodeled.
"""
READS = ()

SOCIETY = {'society', 'societies', 'societal', 'soc', 'soci',
           'société', 'società', 'sociedad', 'ellschaft'}
COMMUNITY = {'community', 'communities', 'communal', 'collective', 'club'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1].strip()
    word = text.lower().lstrip('-_')
    value = 0.0
    if word == 'social':
        value = -2.92 if text == 'social' else -2.78
    elif word in {'socially', 'ocial', 'sociale'}:
        value = -2.2 if word == 'socially' else -1.7
    elif word.startswith(('social', 'socio')):
        value = -1.2
    elif word == '/social':
        value = -2.25
    elif word in SOCIETY:
        value = -1.0
    elif word == 'ociety':
        value = -0.5
    elif text == '社':
        value = -2.67 if prev.endswith(('会', '會')) else -5.4
        if prev.endswith('神'):
            value = -3.9
    elif text in {'社会', '社會', '和社会', '的社会', '社交'}:
        value = -2.5
    elif text in {'社区', '社區'}:
        value = -0.47
    elif '社' in text:
        value = -1.3
    elif word.startswith(('обществ', 'соци')):
        value = -1.1
    elif word in {'со', 'zial', 'コミュニ'}:
        value = -0.6
    elif word in {'xã', '사회'}:
        value = -1.7
    elif word in {'facebook', 'snapchat'}:
        value = -0.95
    elif word in {'instagram', 'twitter'}:
        value = -0.43
    elif word in COMMUNITY:
        value = -0.3
    elif word == '.group':
        value = -0.58
    if prev.lower() == 'social' and value == 0.0:
        value = {'media': -0.5, 'security': -0.36}.get(word, -0.07)
    elif prev.lower() in {'society', 'societies'} and word == 'of':
        value = -0.22
    return (doc, text), value

programs.luna:
"""Mark society-related word pieces with the component's sparse negative sign."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()
    if "soc" in token or "ocial" in token:
        return None, -0.9
    if "社" in token or "обществ" in token:
        return None, -0.9
    return None, 0.0

programs.sol:
"""Closing-parenthesis signal, strongest after short parenthetical text.

Track opening parentheses within each document. A close shortly after an open
has a larger negative response; a distant or unmatched close has less.
Token boundaries matter: a following comma, newline, or semicolon usually
suppresses this signal. Spaces, quotes, nesting, and empty round pairs weaken
it; other bundled symbols, such as an empty square-bracket pair, can amplify it.
Backslash escapes are treated separately. Constants summarize punctuation
classes, not individual token IDs; weak ordinary-text activations are omitted.
"""

import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    opens = [] if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1]
    distance = None
    for c in s:
        if c in '(（':
            opens.append(prefix.position)
        elif c in ')）':
            distance = prefix.position - opens.pop() if opens else None
    short = (math.exp(-max(distance - 2, 0) / 4.0)
             if distance is not None else 0.0)

    if ')' not in s and '）' not in s:
        value = 0.0
    elif s.endswith('）'):
        value = -0.85 - 0.55 * short
    elif not s.endswith(')'):
        if '()' in s:
            value = 0.14 if s[:s.rfind(')')].endswith('(') else 0.0
        elif s.startswith(')') and s[1:] in ('\\', '^', '$', '`', '**'):
            value = -0.07 - 0.15 * short
        elif s[:s.rfind(')')].endswith(('?', '*', '++', '[]', '{}')):
            value = -0.30 - 0.15 * short
        else:
            value = 0.0
    else:
        bare = s.lstrip(' \t')
        if bare == ')':
            if bare != s:
                value = -0.46 - 0.34 * short
            else:
                value = -0.59 - 0.57 * short
                if distance is None:
                    value -= 0.06
        elif bare.endswith('()'):
            value = -0.20
        elif bare.endswith('))'):
            if bare.endswith('())'):
                value = -0.58 - 0.20 * short
            else:
                value = -0.46 - 0.20 * short
        elif bare.endswith('\\)'):
            value = -0.55
        elif bare.endswith('[])'):
            value = -1.50 - 0.60 * short
        elif bare[-2] in ']}':
            value = -0.54 - 0.40 * short
        elif bare[-2] in '\"\'”’':
            value = -0.52 - 0.26 * short
        elif bare[-2] == '.':
            value = -0.94 - 0.55 * short
        else:
            value = -1.05 - 0.80 * short
        if distance == 0 and not bare.endswith('()'):
            value -= 0.55
    if (s == ')' and prefix.position > 0
            and prefix.document_ids[-2] == doc
            and prefix.token_strings[-2].endswith('\\')):
        value = 0.05
    return (doc, opens), value

"""Bracket clusters versus selected body and inner-life nouns.

Positive responses mark repeated or adjoining brackets, block-opening braces,
and a few punctuation operators. Selected English and Chinese human nouns have
negative responses. Possessors strengthen English noun responses; a following
nonblank 'of' repeats that response. Other tokens get zero. The previous
nonblank token and its noun response are forgotten at document boundaries.
"""

READS = ()

# Approximate response strengths within a small, meaningful noun vocabulary.
NOUN_GROUPS = (
    (-2.1, {'hands'}),
    (-1.45, {'eyes', 'minds'}),
    (-1.0, {'mind', 'lips', 'shoulders', 'brains'}),
    (-0.65, {'face', 'mouth', 'nose', 'throat', 'lives', 'voices', 'hearts'}),
    (-0.35, {'faces', 'feet', 'voice', 'bodies', 'heads', 'ears', 'knees'}),
    (-0.15, {'body', 'hand', 'thoughts'}),
)
NOUNS = {word: value for value, words in NOUN_GROUPS for word in words}
POSSESSORS = {'my', 'your', 'his', 'her', 'our', 'their', 'own', "'s", '’s'}
OPEN_PAIRS = {'((': 1.5, '[[': 2.0, '{{': 3.0}
CLOSE_PAIRS = {'))': 0.95, ']]': 1.5, '}}': 1.8}


def brackets(text, previous):
    s = text.strip()
    newline = '\n' in text
    if s in {'{', '{\\'}:
        p = previous.strip()
        if p.endswith(')') or p.endswith('=>') or p in {'else', 'try', 'finally'}:
            value = 1.25 if p.endswith('()') else 1.05
        elif p.endswith((':', '=', ',', '}')) or p == 'return':
            value = 0.0
        else:
            if newline:
                value = 0.75
            elif s == '{\\':
                value = 0.55 if text.startswith(' ') else 0.2
            else:
                value = 0.0
        value += 0.2 if '\r' in text else 0.0
        return value * 0.8 if s == '{\\' else value
    if '{}' in s:
        return 0.2
    if s.endswith('){') or s.endswith('){\\'):
        value = 0.65 if not newline else 1.35
        return value + (0.45 if '++' in s or '--' in s or '()' in s else 0.0)

    value = 0.0
    for pair, weight in OPEN_PAIRS.items():
        if pair in s and not (pair == '((' and '()' in s):
            value = weight + 0.4 * max(0, s.count(pair[0]) - 2)
            quoted = s.startswith(('"', "'", '>', '="'))
            quoted |= previous.rstrip().endswith(('"', "'", '`'))
            if pair == '{{' and (text.startswith(' ') or quoted):
                value += 1.4
            break
    if not value:
        for pair, weight in CLOSE_PAIRS.items():
            if pair in s:
                value = weight + 0.4 * max(0, s.count(pair[0]) - 2)
                if s.startswith('()'):
                    value -= 0.55
                if pair == '}}':
                    value += 0.8 if text.startswith(' ') else 0.0
                    value += 0.3 if s.startswith('"') else 0.0
                    if not newline and previous.rstrip().endswith((']', '"', "'")):
                        value += 0.6
                break
    if not value:
        if '()' in s:
            value = 0.65 - (0.15 if text.startswith(' ') else 0.0)
        elif '[]' in s:
            value = 0.8
        elif any(a + b in s for a in '([{' for b in '([{' if a != b):
            value = 0.85
        elif any(a + b in s for a in ')]}' for b in ')]}' if a != b):
            value = 0.7
        elif s in {'<<', '>>', '{%', '%}'}:
            return 0.15 if s == '>>' and text.startswith(' ') else 0.75
        elif text in {'@@', '~~'}:
            return 0.6
        else:
            return 0.0
    value -= 0.25 if newline else 0.0
    if ';' in s:
        value -= 0.08
    elif ',' in s or '.' in s:
        value -= 0.15
    return max(0.0, value)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, noun = ('', 0.0) if carry is None or carry[0] != doc else carry[1:]
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    value = NOUNS.get(word, 0.0)
    if value:
        value -= 0.3 if previous.strip().lower() in POSSESSORS else 0.0
        if not text.startswith(' ') or text.strip()[0].isupper():
            value *= 0.6
    elif word == 'of':
        value = 1.08 * noun
    elif word in {'脸', '脸上', '眼睛'}:
        value = -0.8
    elif word in {'嘴', '双眼', '心思', '脑袋'}:
        value = -1.3
    elif not any(c.isalnum() for c in text):
        value = brackets(text, previous)
    if text.strip():
        previous, noun = text, value if word in NOUNS else 0.0
    return (doc, previous, noun), float(value)

programs.haiku:
"""Bracket blocks opening or closing in code, and body-part nouns.

What it does: predicts how strongly this component writes "a bracket group is
opening or closing here" into the residual stream, from the current token alone.

- Single bracket characters ("(", ")", "}", "[") are silent.
- Template double braces ("}}", "{{", '"}}\\n', '="{{') are the strongest: about 2.
- A brace that opens a block at line end (" {\\n", "{\\n", " {\\r\\n", " {\\\\"): about 0.9.
- Tokens stacking several round or square brackets ("))", "()", "[]", "(("): about 0.6.
- Tokens stacking braces and parens that close a block (" });", "})"): about 0.3.
- "}{" (one block closed straight into another): 0.
- Body-part nouns push it negative: plurals ("hands", "eyes", "minds") about -0.8;
  singular ones (also 嘴, 脸, 眼) about -0.2, or -0.5 after a possessive ("her mind").

The values are group means fitted on 512 training rows, rounded.
"""

import re

READS = ()

BRACKETS = re.compile(r"[(){}\[\]]")
BODY_PLURAL = {" hands", " eyes", " minds", " lives", " hearts", " feet", " shoulders",
               " arms", " legs", " faces", " mouths", " heads"}
BODY = {" mind", " face", " mouth", " lips", " head", " heart", " body", " soul",
        " thoughts", " voice", " hand", " eye", "嘴", "脸", "眼", "手", "心", "脚"}
POSSESSIVE = {" her", " his", " my", " our", " their", " your", " its"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    n = len(BRACKETS.findall(tok))
    if "{{" in tok or "}}" in tok:
        value = 2.0
    elif "}{" in tok:
        value = 0.0
    elif n >= 2 and "{" in tok:
        value = 1.2 if tok.endswith("\n") else 0.8
    elif n >= 2 and "}" in tok:
        value = 0.3
    elif n >= 2:
        value = 0.6
    elif "{" in tok and ("\n" in tok or "\r" in tok or "\\" in tok):
        value = 0.9
    elif n == 1:
        value = 0.0
    elif tok in BODY_PLURAL:
        value = -0.8
    elif tok in BODY:
        value = -0.5 if prev in POSSESSIVE else -0.2
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""A small directional signal for body-and-mind words and code punctuation."""
READS = ()

BODY_WORDS = {
    "mind", "minds", "life", "lives", "head", "face", "eye", "eyes",
    "ear", "ears", "nose", "mouth", "lip", "lips", "tooth", "teeth",
    "tongue", "neck", "shoulder", "arm", "arms", "hand", "hands",
    "finger", "fingers", "chest", "heart", "body", "skin", "brain",
    "leg", "legs", "foot", "feet",
}
BODY_CHARACTERS = {"眼", "眼睛", "脸", "脸上"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().strip(".,!?;:'\"()[]{}")
    if word.casefold() in BODY_WORDS or word in BODY_CHARACTERS:
        return None, -0.33
    if "{" in token or "}" in token:
        return None, 0.35
    if sum(token.count(char) for char in "()[]<>") >= 2:
        return None, 0.30
    return None, 0.0

"""A sparse lexical sketch of motion, vibration, and excitement.

It scores those word families positively, suggestion-related pieces negatively,
and catches some unspaced endings when a known word is split into tokens.
"""

READS = ()

ACTIVE_STEMS = (
    "shake", "shook", "vibrat", "oscill", "bounc", "excit", "thrill",
    "intrigu", "revital", "reviv", "vigor", "scatt", "quake", "trembl",
    "shiver", "wobbl", "swing", "jolt", "teas", "exhilar",
)
MOTION_CHARACTERS = set("振震摆擺搖摇晃抖颤顫翔")
ENERGY_CHARACTERS = set("兴興奋奮激")
CONTINUED_ENDINGS = ("ation", "ations", "ion", "ions", "ing", "ed", "ement")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if "suggest" in word:
        return None, -0.42
    if "oscill" in word:
        return None, 0.84
    if "excited" in word or "shook" in word:
        return None, 0.76
    if any(stem in word for stem in ACTIVE_STEMS):
        return None, 0.48
    if any(char in word for char in MOTION_CHARACTERS):
        return None, 0.68
    if any(char in word for char in ENERGY_CHARACTERS):
        return None, 0.56

    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].strip().casefold()
        current = prefix.token_strings[-1].casefold()
        if not current[:1].isspace():
            if any(stem in previous for stem in ("oscill", "vibrat", "excit", "shake")):
                if current.startswith(CONTINUED_ENDINGS):
                    return None, 0.52
    return None, 0.0

programs.sol:
"""Approximate salient signed responses to commercial noun compounds.

Agents, brokers, trade/tax vocabulary, departments, and storage/retail words
receive negative values, strengthened after business or material modifiers.
Classification words and products can instead be positive. Small lexical
baselines cover quantities, modals, time words, and the opening reasoning tag.
This captures recognizable cases, not most unrelated lexical fluctuations.
"""
READS = ()

AGENTS = {'agent', 'agents'}
BROKERS = {'broker', 'brokers', 'brokerage'}
CLERKS_DEALERS = {'clerk', 'clerks', 'dealer', 'dealers'}
TRADE = {'trade', 'trading'}
TAX_LOSS = {'tax', 'taxes', 'loss', 'losses'}
DEPARTMENTS = {'commission', 'commissions', 'department', 'departments'}
STORAGE = {'tank', 'tanks', 'yard', 'yards', 'garage', 'garages',
           'elevator', 'elevators', 'pantry', 'refrigerator'}
CATEGORIES = {'type', 'types', 'class', 'classes', 'form', 'forms',
              'style', 'styles', 'species'}
DOMAINS = {
    'rental', 'estate', 'administrative', 'mortgage', 'stock', 'securities',
    'financial', 'clearing', 'freight', 'shipping', 'sales', 'income',
    'commerce', 'exchange', 'revenue', 'tax', 'loan', 'labor',
    'transportation', 'retail', 'wholesale', 'licensed', 'registered',
    'fuel', 'storage', 'water', 'oil', 'gas', 'rail', 'lumber', 'grocery', 'food',
}
CLASS_MODIFIERS = {'asset', 'property', 'tax', 'housing', 'room',
                   'soil', 'marine', 'plant'}
NEGATIVE_NOUNS = AGENTS | BROKERS | CLERKS_DEALERS | TRADE | TAX_LOSS
NEGATIVE_NOUNS |= DEPARTMENTS | STORAGE

WORD_CLASSES = (
    (AGENTS, -0.02),
    (BROKERS, -0.24),
    (CLERKS_DEALERS, -0.13),
    (TRADE, -0.18),
    (TAX_LOSS, -0.08),
    (DEPARTMENTS, -0.09),
    (STORAGE, -0.17),
    (CATEGORIES, 0.02),
    ({'product'}, 0.01),
    ({'products'}, 0.08),
    ({'grocery'}, -0.36),
    # Quantity/comparison words, modals, and temporal expressions.
    ({'some', 'any', 'few', 'more', 'much', 'other',
      'certain', 'several', 'least', 'every'}, -0.04),
    ({'will', 'may', 'must', 'maybe'}, 0.035),
    ({'next', 'prior', 'early'}, -0.08),
    ({'now', 'again'}, 0.065),
)
BASE = {word: value for words, value in WORD_CLASSES for word in words}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = -0.27 if token == '<think>' else BASE.get(word, -0.0015)
    if word in NEGATIVE_NOUNS:
        if previous == 'insurance':
            value -= 0.57 if word in AGENTS else 0.40
        elif previous in DOMAINS:
            value -= 0.22
    if word in CATEGORIES and previous in CLASS_MODIFIERS:
        value += 0.22
    if word in {'product', 'products'} and previous in DOMAINS | {'insurance'}:
        value += 0.16
    if previous == 'tax' and word in {'return', 'returns'}:
        value = -0.27
    # A tokenization split of "brokerage(s)" retains a negative response.
    if previous in BROKERS and word in {'age', 'ages'}:
        value = -0.33
    return (doc, word), float(value)

programs.luna:
"""Mark the distinctive phrase "insurance agent/broker" and "trading".

The component's clearest high-impact examples are strongly negative on agent
and broker immediately after insurance, and on trading; this compact rule
leaves its weaker, inconsistent responses to other text unmodeled.
"""

READS = ()

def _word(token):
    return token.strip().casefold().strip(".,!?;:'\"()[]{}")


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    if word == "trading":
        return None, -0.30
    if word not in {"agent", "broker", "age"}:
        return None, 0.0

    end = len(prefix.token_strings)
    if end >= 2 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = _word(prefix.token_strings[-2])
        if word in {"agent", "broker"} and previous == "insurance":
            return None, -0.70
        if (word == "age" and previous == "broker" and end >= 3
                and prefix.document_ids[-3] == prefix.document_ids[-1]
                and _word(prefix.token_strings[-3]) == "insurance"):
            return None, -0.70
    return None, 0.0

programs.sol:
"""Predict indentation and alignment whitespace, not ordinary words.

Space-run width and tabs determine the main response. A preceding line break
reduces it, especially after blank lines or trailing spaces. Code separators
and opening delimiters counteract that reduction. Literal escaped tabs and
newlines are treated as layout too. Two preceding token strings are retained;
this tiny context resets at every document boundary.
"""
READS = ()

# Each punctuation correction gives (one space, longer whitespace runs).
AFTER_BREAK = {
    '{': (0.55, 1.30), '(': (0.24, 1.18), '[': (0.05, 0.87),
    ';': (0.58, 0.93), ',': (0.72, 1.07), '}': (0.08, 0.33),
    ')': (0.24, 0.40), ':': (0.03, 0.17), '.': (-0.28, -0.47),
    '>': (0.09, 0.25), '"': (0.06, 0.26), "'": (0.06, 0.26),
}
INLINE = {
    ':': (0.36, 0.83), ',': (0.12, 0.04), '=': (0.23, -0.04),
    '.': (-0.08, -0.35), ')': (0.13, 0.07), '|': (0.03, 0.27),
    ';': (0.28, 0.54),
}
TAB_AND_SPACES = {
    1: 2.28, 3: 1.67, 5: 2.59, 7: 2.08,
    9: 2.64, 11: 2.34, 15: 2.20,
}


def whitespace_score(s, previous, before_previous, start):
    if s == '\\t':
        if start:
            return -0.15
        if previous.endswith('\\n'):
            return 0.41
        split_newline = previous == 'n' and before_previous.endswith('\\')
        return 0.86 if split_newline else 0.71
    if s == '\x0c':
        return -2.18
    if not s.isspace() or s in (' \n', ' \n\n'):
        return 0.0
    h = s.rstrip('\r\n')
    if not h or h.strip(' \t\xa0'):
        return 0.0
    if h == '\xa0':
        if '\n' in s:
            return -0.22
        return -0.8 if '\n' in previous else 0.1
    n, tabs = h.count(' '), h.count('\t')
    if tabs and n:
        if start:
            return 0.1
        value = TAB_AND_SPACES.get(n, 1.80)
        return value - 0.65 * ('\n' in previous) - 0.75 * ('\n' in s)
    single = h == ' '
    column = 0 if single else 1
    if '\xa0' in h:
        value = 1.08
    elif tabs:
        value = 1.61 if tabs == 1 else 1.78 if tabs == 2 else 1.46
    else:
        value = 1.10
        for width, score in ((1, 0.04), (2, 0.74), (5, 1.44),
                             (10, 1.74), (16, 1.51), (24, 1.25)):
            if n <= width:
                value = score
                break
    if start:
        return value - (0.15 if single else 0.75)
    if '\n' in previous:
        value -= 1.49 if single else 1.39
        value -= (0.38 if single else 0.75) * (previous.count('\n') >= 2)
        value -= (0.02 if single else 0.08) * ('\r' in previous)
        line = previous.rstrip('\r\n')
        value -= (0.24 if single else 1.05) * line.endswith(' ')
        ending = line.rstrip()[-1:]
        value += AFTER_BREAK.get(ending, (0.0, 0.0))[column]
        if not line.strip() and not single:
            # A separately tokenized newline can hide the line's punctuation.
            ending = before_previous.rstrip()[-1:]
            correction = AFTER_BREAK.get(ending, (0.0, 0.0))[1]
            value += -0.7 if ending == '.' else 0.5 * correction
        if line.rstrip().endswith(('=>', '||', '&&')) and not single:
            value += 0.55 if ending == '>' else 0.8
        value += (0.17 if single else 0.04) * line.startswith(' ')
    elif previous.isspace():
        value += 0.04 if single else -0.39
    else:
        p = previous.strip()
        if p.endswith('\\n'):
            value -= 0.16 if single else 0.65
        else:
            value += INLINE.get(p[-1:], (0.0, 0.0))[column]
            if single and len(p) > 1:
                compound = {':': 0.23, ',': 0.15, '=': 0.32}
                value += compound.get(p[-1:], 0.0)
        value -= (0.05 if single else 0.06) * p.isdigit()
        if previous == 'n' and before_previous.endswith('\\'):
            value += 0.32 if single else 0.48
    if '\n' in s and not single:
        value -= 0.28 + 0.44 * bool(tabs)
