import re

READS = ()
IRREGULAR_PLURALS = {
    'people', 'men', 'women', 'children', 'feet', 'teeth', 'mice',
    'geese', 'oxen', 'criteria', 'phenomena', 'nuclei',
}
PLURAL_PRONOUNS = {
    'we', 'they', 'you', 'them', 'us', 'these', 'those', 'both',
    'ourselves', 'yourselves', 'themselves',
}
NONPLURAL_S = {
    'this', 'his', 'its', 'is', 'was', 'has', 'does', 'yes', 'as',
    'thus', 'perhaps', 'always', 'sometimes', 'whereas', 'diabetes',
    'analysis', 'axis', 'basis', 'iris', 'penis', 'metropolis',
    'christmas', 'gas', 'chaos', 'cosmos', 'lens', 'bias', 'atlas', 'texas',
    # Common nonplural word stems / prefixes.
    'trans', 'dis', 'des', 'mis', 'res', 'pres', 'phys',
}
MEASUREMENTS = {
    'time', 'speed', 'temperature', 'pressure', 'length', 'height',
    'width', 'weight', 'distance', 'volume', 'frequency', 'density',
    'size', 'age', 'cost', 'price', 'rate', 'energy', 'velocity',
    'acceleration', 'force', 'mass', 'load', 'capacity', 'power',
    'voltage', 'current',
}
# Each pair is (ordinary offset, response to the preceding number signal).
CONNECTIVES = {
    'and': (0.005, 1.318),
    'or': (-0.030, 0.806),
    'nor': (-0.030, 0.806),
    '&': (-0.053, 0.638),
    'are': (0.038, 0.595),
    'were': (-0.078, 0.366),
    'have': (-0.018, 0.290),
    'is': (0.005, -0.488),
    'was': (-0.062, -0.536),
    'has': (-0.036, -0.273),
    'does': (0.038, -0.160),
    'per': (-0.035, 0.382),
    ',': (-0.019, 0.181),
    '.': (-0.006, 0.041),
    '-': (0.006, -0.258),
}


def number_strength(word, token):
    if token.endswith(("'s", '’s')):
        return 0.0
    if word in IRREGULAR_PLURALS:
        return 0.76
    if word in {'data', 'news', 'series', 'species', 'means'} or word.endswith('ics'):
        return 0.50
    if word in PLURAL_PRONOUNS:
        return 0.28
    if word == 's':
        return 0.46
    if word in NONPLURAL_S or word.endswith(('ss', 'ous', 'us', 'sis', 'xis', 'itis')):
        return 0.0
    return 1.0 if word.endswith('s') else 0.0


def response(token):
    word = token.strip().lower()
    if word in {'-and', '_and', '_or'}:
        word = word.lstrip('-_')
    if word in CONNECTIVES:
        return CONNECTIVES[word]
    if word in {'et', 'und', 'y'}:
        return -0.018, 0.517
    if word in {'their', 'our', 'your'}:
        return 0.0, 0.182
    if word in MEASUREMENTS:
        return -0.006, -0.340
    if word in {"'", '’'}:
        return -0.008, 0.648
    if word in {"'s", '’s'}:
        return 0.026, -0.227
    if token.startswith('/'):
        return -0.017, 0.434
    if word in {'of', 'in', 'by', 'that', 'you', 'it', 'this'}:
        return -0.001, -0.092
    if word in {'to', 'the', 'with', 'for', 'a', 'as', 'all'}:
        return -0.005, 0.036
    if token.isspace():
        return 0.001, -0.203
    if word.isdigit():
        return 0.0, -0.256
