        if token[0].islower():
            return -0.002, 0.149
        return (-0.007, 0.054) if token.isupper() else (0.004, -0.382)
    if any(c.isalpha() for c in token):
        if token.startswith('_'):
            return 0.014, -0.285
        if token.startswith('-'):
            return 0.002, -0.378
        if token.startswith('.'):
            return -0.010, 0.110
    if token.startswith(' ') and word.isascii() and word.isalpha():
        return (0.004, -0.054) if token.strip()[0].islower() else (0.008, -0.160)
    return 0.0, 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, previous_token = ('', '') if first else carry[1:]
    strength = number_strength(previous.lower(), previous_token)
    if token.lstrip(' \t').startswith(('\n', '\r')):
        strength = 0.0
    base, slope = response(token)
    value = base + strength * slope
    match = re.search(r'[A-Za-z]+\Z', previous + token)
    tail = match.group()[-64:] if match else ''
    if first:
        value -= 0.24 * number_strength(tail.lower(), token)
    return (doc, tail, token), float(value)

