"""Adverb detector (layers.0.mlp.down_proj:4299, layer 0).

What it responds to: the token that completes an adverb. The component goes strongly
NEGATIVE on -ically adverbs built on -ic and -al adjectives ("statistically", "visually",
"clinically": about -3 to -6), moderately negative on other -ally/-ly adverbs
("originally", "partially", "generally", "previously": about -0.6 to -2), and weakly negative
on the -mente and -wise adverbs of other languages and words like "automatically". It is
POSITIVE on the manner adverbs "easily" and "readily" (about +1.8), "quickly" (+0.6), the
Chinese adverb marker 地 (+0.6), and the "0" of a year after "2" ("2018": about +0.55).
Frequent words that only look like adverbs (really, only, family, likely, ...) stay at 0.

Stateless: reads only the current token and the one before it.
"""

READS = ()

NOT_ADVERBS = {
    "really", "finally", "only", "early", "family", "likely", "probably", "simply",
    "especially", "apply", "supply", "reply", "friendly", "daily", "july", "holy",
    "correctly", "successfully", "assembly", "lovely", "lively", "rely", "typically",
    "basically", "practically", "actually", "specifically",
}
MANNER_POSITIVE = {"easily": 1.8, "readily": 1.8, "quickly": 0.6, "地": 0.6}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""

    if word == "0" and previous == "2":
        value = 0.55  # the 0 of a year such as 2018
    elif word in MANNER_POSITIVE:
        value = MANNER_POSITIVE[word]
    elif word in NOT_ADVERBS:
        value = 0.0
    elif word.endswith("ically") and len(word) >= 6:
        value = -3.3  # adverb from an -ic/-al adjective: statistically, visually
    elif word.endswith("ally") or word.endswith("ually"):
        value = -1.7  # adverb from an -al adjective: originally, generally
    elif word.endswith("ly") and len(word) >= 5:
        value = -0.6  # other -ly adverbs: previously, currently, highly
    elif word.endswith("mente") or word.endswith("wise"):
        value = -0.6  # adverb-forming suffixes in other languages, -wise
    else:
        value = 0.0
    return carry, float(value)

