# Fold corresponding letters across Latin, Cyrillic, Greek and Arabic scripts.
LETTER_FAMILIES = (
    ('aаαا', 'a'), ('iиιیيі', 'i'), ('oоοω', 'o'), ('uуυو', 'u'),
    ('eеεэ', 'e'), ('hхه', 'h'), ('rрρر', 'r'), ('lлλل', 'l'),
    ('yыяюъ', 'y'), ('tтτت', 't'), ('nнνن', 'n'), ('mмμم', 'm'),
    ('kкκكک', 'k'), ('dдδد', 'd'), ('gгγگغ', 'g'), ('pпπپ', 'p'),
    ('sсσςس', 's'), ('zзζز', 'z'), ('fфφف', 'f'),
)
FOLD = {ord(c): replacement for chars, replacement in LETTER_FAMILIES
        for c in chars}
FIRST = {
    'a': 1.09, 'i': 0.33, 'o': 0.25, 'u': 0.50,
    'e': -0.24, 'r': -0.17, 'l': -0.03, 'h': -1.00,
    'y': 0.33, 'j': 0.55, 'f': -0.20,
}


@lru_cache(maxsize=8192)
def spelling(token):
    text = ''.join(c for c in unicodedata.normalize('NFD', token.lower())
                   if not unicodedata.combining(c))
    return text.translate(FOLD)


def second_letter(piece):
    c = piece[1:2]
    if not c:
        return 0.10
    if c in 'mn':
        return 0.33
    if c == 't':
        return 0.48
    if c in 'cdgkp':
        return 0.22
    if c in 'sxz':
        return 0.37
    if c == 'r':
        return -0.38
    if c == 'h':
        return -0.12
    if c == 'w':
        return 0.46
    if c in 'aeiouy':
        return 0.02
    return 0.10


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    piece = spelling(token)
    value = 0.0
    if carry and carry[0] == doc and piece and piece[0].isalpha():
        previous, uppercase = carry[1:]
        strength = 0.0
        if previous.endswith('t'):
            strength = 1.29 if uppercase else 1.0
        elif previous.endswith(('th', 'te')):
            strength = 0.34
        if strength:
            value = FIRST.get(piece[0], 0.06) + second_letter(piece)
            if piece.startswith('ing'):
                value -= 0.53
            if piece.startswith('ion'):
                value -= 0.67
            if piece == 'e':
                value -= 0.47
            value *= strength * math.exp(
                -0.20 * max(len(piece) - 2, 0)
                -0.20 * max(len(previous.lstrip()) - 2, 0))
            if len(piece) == 1:
                value *= 0.65
    uppercase = bool(token) and token[-1].isupper()
    return (doc, piece, uppercase), value

