"""A g/G spelling detector with a short continuation trace.

Isolated G, and more weakly g, give negative activations. The detector also
covers a few related letter forms, the name gamma, and Japanese g-syllables.
Short fragments and nearby repeated g's matter more than complete long words.
A final g affects the next token, especially a joined continuation containing
another g. Isolated document-initial letters have unusually large responses.
This approximates spelling sensitivity, not the component's lexical nuances.
"""
READS = ()
G_FORMS = frozenset('gGгГγΓگ')
G_TRANSLATION = str.maketrans({'г': 'g', 'γ': 'g', 'گ': 'g'})
RELATED = {
    'Г': (-0.80, -0.64),
    'г': (-0.30, -0.40),
    'Γ': (-0.30, -0.31),
    'γ': (-0.74, -0.50),
    'گ': (-0.88, -0.88),
}


def spelling_value(text):
    word = text.strip()
    lower = word.lower()
    spaced = text != text.lstrip()
    if word == 'G':
        return -0.95 if spaced else -0.79
    if word == 'g':
        return -0.50 if spaced else -0.45
    if word in RELATED:
        return RELATED[word][int(spaced)]
    if lower == 'gamma':
        return -0.55
    if len(word) == 1 and word in 'ぎぐげごガギグゲゴ':
        return -0.36

    letters = ''.join(c for c in word if c.isalpha())
    if letters in ('g', 'G'):
        if word.startswith('.'):
            return -0.82 if letters == 'G' else -0.21
        if word.startswith(('(', '[')):
            return -0.56 if letters == 'G' else -0.50
        return -0.84 if letters == 'G' else -0.73
    if lower.endswith('gg') and len(word) <= 5:
        if word.isupper():
            return -1.20
        return -0.88 if len(word) == 2 else -0.37
    if lower.endswith('ng'):
        return 0.0
    if lower.endswith('g') and len(word) <= 4:
        if word.isupper() and len(word) == 2:
            return -0.37
        if lower.endswith('rg'):
            return -0.18
        if len(word) > 1 and lower[-2] not in 'aeiou':
            return -0.30 if len(word) == 2 else -0.11
        return -0.025
    if lower.startswith('g') and len(word) == 2:
        second = lower[1]
        if second == 'a':
            return -0.77 if word[0] == 'G' else -0.61
        if second == 'r':
            return 0.0 if word[0] == 'G' else 0.16
        if second == 's':
            return -0.56
        if second in 'eiu':
            return -0.32 if word[0] == 'G' else -0.13
        return -0.10
    return -0.10 if lower.startswith('ga') else 0.0


