    doc = int(prefix.document_ids[-1])
    text = prefix.token_strings[-1]
    word = text.strip()
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    current_g = text.lower().translate(G_TRANSLATION)
    previous_g = previous.lower().translate(G_TRANSLATION)
    has_g = 'g' in current_g
    joined = text == text.lstrip()
    value = spelling_value(text)

    if previous_g.endswith('g'):
        if joined:
            if previous.strip() in G_FORMS:
                value -= 0.09
            if has_g:
                value -= 0.11
            if len(previous.strip()) <= 4:
                if current_g.startswith('g'):
                    value -= 1.53
                elif 'g' in current_g[:3]:
                    value -= 0.59
                if text and text[0].lower() in 'aeiou':
                    value -= 0.295 if len(text) <= 3 else 0.13
                elif text[:1].isalpha() and not has_g and len(text) <= 3:
                    value -= 0.20
                if 'gg' in previous_g:
                    value -= 0.18
            if word in ('g', 'G'):
                value -= 1.29 if word == 'G' else 0.27
            if previous.strip() in RELATED:
                value -= 0.11
        elif has_g:
            value -= 0.075
    elif 'g' in previous_g and word in ('g', 'G'):
        value -= 0.265

    if first and text in ('G', 'g', ' G'):
        value = {'G': -4.24, 'g': -3.27, ' G': -3.31}[text]
    return (doc, text), float(value)

