            (24, -0.2), (32, 1.0), (64, 0.8))


def interpolate(n, points):
    if n <= points[0][0]:
        return points[0][1]
    for (x, y), (xx, yy) in zip(points, points[1:]):
        if n <= xx:
            return y + (yy - y) * (n - x) / (xx - x)
    return points[-1][1]


def spaces(n, indent):
    if n <= 20:
        shift = 0.074 if n == 1 else -min(0.12 * n, 0.78)
        if n >= 7 and n % 4 == 3:
            shift -= 0.20
        return SPACE_RUN[n] + (shift if indent else 0.0)
    value = interpolate(n, ((20, -0.87), (22, 0.24), (28, 1.98),
                            (34, 2.3), (42, 2.04), (50, 1.61),
                            (62, 0.39), (64, 0.9), (128, 0.9)))
    if n % 4 == 3 and n < 64:
        value -= 0.75
    return value - (0.8 if indent and n < 64 else 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    indent = carry is not None and carry[0] == doc and carry[1]
    value = 0.0
    if s and s.isspace():
        tabs = s.count('\t')
        n = s.count(' ')
        if '\n' in s or '\r' in s:
            lines = s.replace('\r', '').split('\n')
            longest = max(lines, key=len)
            if tabs and not n:
                t = max(line.count('\t') for line in lines)
                value = 0.04 if t == 1 else interpolate(4 * t, LINE_END)
            else:
                value = interpolate(len(longest), LINE_END)
        elif s.strip(' ') == '':
            value = spaces(n, indent)
        elif s.strip('\t') == '':
            value = TAB_RUN[min(tabs, 11)] - (0.9 if indent else 0.0)
        elif s.strip('\t ') == '' and tabs == 1:
            value = interpolate(n, TAB_SPACES) - (0.8 if indent else 0.0)
        elif s.strip('\t ') == '':
            if s.startswith(' '):
                value = TAB_RUN[min(tabs, 11)] + 0.4 - (0.9 if indent else 0.0)
            else:
                value = spaces(n + 4 * tabs, True) - 0.3
        elif s.strip(' \xa0') == '' and len(s) > 1:
            value = 0.8 * spaces(len(s) + 4, False)
    else:
        bar = s.strip()
        if len(bar) >= 8 and bar[0] in '-=_.#*~/' and len(set(bar)) == 1:
            n = len(bar)
            value = 0.65 * spaces(n, False)
    return (doc, s.endswith(('\n', '\r'))), float(value)

"""Negative responses to third-person subject-pronoun-shaped tokens.

He/she are strongest, followed by it, they and who. Initial capitals,
punctuation boundaries and early document positions generally strengthen
the response; all-capital spellings have separate strengths. Unspaced 'it'
inside a word is much weaker. Sheet and heat words also respond, and a few
possessive/object pronouns get small values. Everything else gets zero.
This is token-shape recognition, not full grammatical analysis.
"""
import math

READS = ()

# Word: lowercase, capitalized, unspaced lowercase, unspaced capitalized.
SUBJECTS = {
    'he':   (-2.88, -4.28, -3.95, -4.45),
    'she':  (-3.53, -4.50, -4.00, -4.85),
    'it':   (-1.21, -1.69, -1.29, -1.73),
    'they': (-0.92, -1.55, -1.30, -1.78),
    'who':  (-1.11, -1.25, -1.30, -1.28),
}
CAPITALS = {'he': -2.8, 'she': -5.7, 'it': -1.04,
            'they': -1.6, 'who': -0.6}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = carry[1] + 1 if carry and carry[0] == doc else 0
    state = (doc, position)
    token = prefix.token_strings[-1]
    word = token.lstrip(' \t\r\n.\"\'“”‘’/—-')
    leading = token[:len(token) - len(word)]
    lower = word.lower()
    if lower not in SUBJECTS:
        if lower in {'sheet', 'heet', 'sheets', 'heets'}:
            return state, -1.75 if lower.endswith('s') else -2.35
        if lower in {'heat', 'heating', 'heater', 'heaters'}:
            return state, -0.85
        if leading.isspace():
            return state, {'their': 0.22, 'his': 0.16, 'its': 0.09,
                           'us': 0.25, 'His': -0.21, 'Her': -0.17}.get(word, 0.0)
        return state, 0.0
    if word.isupper():
        return state, -0.31 if lower == 'it' and not leading else CAPITALS[lower]
    if word not in {lower, lower.capitalize()}:
        return state, 0.0
    capital = word.istitle()
    human = lower in {'he', 'she'}
    previous = prefix.token_strings[-2] if position else ''
    boundary = not previous or not previous[-1:].isalnum()
    spaced = bool(leading) and leading.isspace()
    value = SUBJECTS[lower][int(capital) + (0 if spaced else 2)]
    if not spaced and not leading and not boundary and not capital:
        if lower == 'it':
            value = -0.24
        elif lower == 'he':
            value = -2.58
        elif lower == 'they':
            value = -0.82
    if spaced and boundary and not capital:
        value -= 0.35 if lower == 'he' else 0.11 if lower == 'who' else 0.21
    slope = 0.14 if capital and human else 0.08 if human else 0.03
    value += slope * math.log((position + 1) / 128)
    if position == 0 and human:
        value = -6.5 if capital else -4.75
    return state, float(value)

