PUNCTUATION = {
    '%': (-0.023, 0.33), '[': (-0.002, 0.24), ']': (0.022, 0.28),
    '"': (0.007, 0.16), "'": (0.009, 0.18), '#': (0.013, 0.17),
    '/': (-0.001, 0.11), '\\': (0.018, 0.08),
    '“': (-0.004, 0.053), '”': (-0.011, 0.14),
    '‘': (-0.039, 0.10), '’': (-0.017, 0.23),
