    in_east_text = recent > 0.1
    value = 0.0007

    if token in PUNCTUATION:
        value = PUNCTUATION[token][int(in_east_text)]
    elif token.startswith(' ') and s in PUNCTUATION:
        # Spaced punctuation is less sensitive to the surrounding script.
        value = 0.003
    elif token.isspace() and '\n' in token:
        value = -0.025 if in_east_text else 0.002
    elif len(s) == 1 and s in '0123456789':
        value = DIGITS[int(s)] - (0.016 if in_east_text else 0.0)
    elif s == '<|endoftext|>':
        value = 0.147 if in_east_text else -0.020
    elif s == '<|im_start|>':
        value = -0.113 if start else -0.004
    elif s == '</think>':
        value = -0.12
    elif s == '</tool_call>':
        value = -0.061 if start else 0.078
    elif s == '#include':
        value = -0.231 if start else -0.134
    elif s in {'import', 'package'}:
        value = 0.067 if start else 0.026
    elif '_' in s:
        value = -0.014
    elif token.startswith(' ') and s == 'am':
        value = -0.070
    elif token.startswith(' ') and s == 'from':
        value = -0.022
    elif token.startswith(' ') and s in {'not', 'no', 'never', 'neither'}:
        value = -0.012

    if start and s and set(s) == {'#'}:
        value = 0.19
    elif start and s == '//':
