READS = ()

# Compact pieces ending in a liquid consonant (l/r) followed by s.
LIQUID_S = {
    'els': -1.15, 'ils': -0.61, 'ols': -1.41, 'uls': -1.01,
    'ars': -0.60, 'ers': -0.31, 'ors': -0.60, 'urs': -0.43,
    'rs': -0.70,
}
