              'preference', 'preferences'}


def response(token):
    word = token.strip()
    lower = word.lower()
    space = token[:1].isspace()
    if word == 'Als':
        return -4.4
    if lower == 'als':
        return -2.0 if word.isupper() else (-3.63 if space else -1.69)
    if lower == 'ls':
        return -2.2 if word.isupper() else (-2.62 if space else -2.04)
    if word in ('ELS', 'ARS'):
        return -2.0 if word == 'ELS' else -1.3
    if lower in LIQUID_S:
        if space and lower in ('ers', 'els'):
            return -1.05 if lower == 'ers' else -1.48
        return LIQUID_S[lower]
    if lower in ('cls', 'tls'):
        return -1.34 if lower == 'tls' else (-0.96 if space else -1.75)
    if lower.lstrip('.-_/') == 'js':
        if token == '.js':
            return -0.26
        return -0.49 if word != lower else (-0.77 if space else -1.0)
    if word == 'As':
        return -0.42
    if space and lower in ('los', 'las', 'les', 'os'):
        return -0.37 if lower in ('los', 'os') else -0.13
    if token in ('尔', '爾', '耳'):
        return -1.18
    if token in ('ル', 'ール'):
        return -0.69
    if lower == 'readme':
        return 1.30 if space else 1.03
    if lower.lstrip('_') in ('requirement', 'requirements'):
        return 2.06 if lower.endswith('s') else 1.73
    if lower in ('dependency', 'dependencies'):
        return (1.12 if lower.endswith('ies') else 0.84) if space else 0.57
    if lower in ('expectation', 'expectations'):
        return 0.98 if lower == 'expectation' else 0.61
    if lower in ('opportunity', 'opportunities'):
        return 0.79 if lower == 'opportunity' else 0.54
    if lower in ASSUMPTIONS_AND_PREFERENCES:
        return 0.53
    if token in ('需求', '的需求') or lower == 'требования':
        return 0.79 if token == '的需求' else 1.2
    return 0.0


