    return None, float(response(prefix.token_strings[-1]))

"""A small spelling-based approximation, with explicit character exceptions.

Short lowercase-w fragments are positive, particularly pw and passages
with many such fragments; a space-prefixed single w is usually negative.
The spelling ' de' is stronger initially or in fragment-rich passages.
Two unrelated negative effects are retained: the closing angle quote,
and an isolated byte fragment completing the katakana syllable wa.
Fragment responses are conservatively scaled using held-out training rows.
Most small, token-specific background activations are left near zero.
"""
READS = ()
WHOLE_WORDS = {
    'new', 'how', 'now', 'low', 'two', 'own', 'saw', 'few', 'row',
    'show', 'grow', 'know', 'law', 'bow', 'cow', 'flow', 'view',
    'away', 'slow', 'draw', 'snow', 'wow', 'throw', 'below',
    'we', 'was', 'with', 'will', 'were', 'who', 'why', 'what',
    'way', 'win', 'work', 'when', 'well',
}


def fragment_kind(s):
    word = s.strip()
    letters = ''.join(c for c in word if c.isalpha())
    if 'w' not in word or not 1 <= len(letters) <= 4:
        return None
    if word == 'we' and not s.startswith(' '):
        return 'other'
    if word.lower() in WHOLE_WORDS:
        return None
    if letters == 'w':
        return 'word_initial' if s.startswith(' ') else 'other'
    if word.endswith('w'):
        return 'other'
    if not s.startswith(' ') and len(word) == 2 and word[0] == 'w':
        if word[1] in 'aiouysdt':
            return 'other'
    return None


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0)
    doc, position, fragments = carry
    s = prefix.token_strings[-1]
    kind = fragment_kind(s)
    value = -0.002
    density = fragments / max(position, 1)
    if s == '›':
        value = -0.34
    elif position > 0 and s == '�' and (
        prefix.text_prefixes[-1].endswith('ワ')
    ):
        value = -0.71
    elif s == ' de':
        if position == 0:
            value = 0.784
        else:
            value = 1.01 if density > 0.06 else 0.025
    elif kind is not None:
        if density > 0.15:
            value = 0.96
        elif kind == 'word_initial':  # a space-prefixed, single-letter w
            value = -0.09
        elif s.endswith('pw'):
            value = 0.80
        elif position < 2:
            value = 0.54
        elif density > 0.02:
            value = 0.18
        else:
            value = 0.075
        value *= 0.75
    carry = (doc, position + 1, fragments + (kind is not None))
    return carry, float(value)

"""A negative lexical detector for experience and empirical practice.

