READS = ()

# Each row is a related word family, with its typical negative magnitude.
FAMILIES = (
    (1.9, 'experienced experiencing perienced'),
    (2.7, 'perience periences experi'),
    (1.4, 'inexperienced personally'),
    (0.95, 'practices practical practicing practiced practise'),
    (0.7, 'practitioner practitioners pract'),
    (1.15, 'empirical empir empirically trials'),
    (0.94, 'tested'),
    (0.55, 'trial hands exposure exposed expertise encounter encountered pilot'),
    (0.35, 'observation observations demonstrated proven feedback'),
    (0.23, 'seen observed personal'),
    (2.0, 'firsthand expérience expériences'),
    (2.7, 'experiencia experiencias experiência experiências 경험 ประสบ'),
    (2.1, 'erfahrung erfahrungen ahrungen'),
    (1.6, 'практи prakt'),
    (0.7, 'ahrung erf'),
)
LEXICON = {w: m for m, words in FAMILIES for w in words.split()}


def strength(raw):
    word = raw.strip().lower()
    if word in {'experience', 'experiences'}:
        return (4.0 if word == 'experience' else 3.6) if raw.startswith(' ') else 3.1
    if word == 'practice':
        return 1.55 if raw.startswith(' ') and raw.strip().islower() else 1.2
    if word.startswith('experiment') or word in {'periment', 'periments'}:
        return 1.15
    if word in {'testing', 'tests', 'test'}:
        if not raw.startswith(' '):
            return -0.08
        return {'testing': 0.4, 'tests': 0.26, 'test': 0.0}[word]
    if '经验' in word or '經驗' in word:
        return 5.0
    if word in {'实践', '實踐', '実践', '践', '踐'}:
        return 3.7
    if word in {'体验', '體驗', '经历', '經歷', '亲身', '親身'}:
        return 2.1
    if word in {'试验', '試驗', '试点', '試點'}:
        return 1.7
    if word in {'实验', '實驗', '实际', '實際'}:
        return 1.1
    if word.startswith('опыт') or word == 'опы':
        return 2.4
    return LEXICON.get(word, 0.002)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, older, previous_strength = '', '', 0.0
    if carry is not None and carry[0] == doc:
        _, previous, older, previous_strength = carry
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    base = strength(raw)
    magnitude = base
