            magnitude = 2.5 if tail.endswith('経験') else 2.1
    if word in {'experience', 'experiences'}:
        if previous == 'practical' or (previous in {'-on', 'on'} and older == 'hands'):
            magnitude += 3.4
        elif previous in {'personal', 'professional', 'work',
                          'relevant', 'past', 'extensive'}:
            magnitude += 1.3
        elif previous in {'my', 'our', 'their', 'own', 'of'}:
            magnitude += 0.6
        elif previous in {'user', 'customer', 'shopping',
                          'viewing', 'gaming', 'browsing'}:
            magnitude -= 0.9
    factors = {'of': 0.54, 'with': 0.57, 'in': 0.33, 'from': 0.21}
    if word in factors and previous_strength > 0.2:
        magnitude += factors[word] * previous_strength
