        magnitude = 1.5
    return (doc, word, previous, base), float(-magnitude)

"""A capital-run boundary detector with an explicit NAME_ placeholder rule.

Capital runs accumulate across uppercase tokens and reset at other text.
Continuing a run is mildly positive, especially at a new uppercase word;
ending one with mixed-case text or punctuation is negative.  NAME_ is a
stronger, separately calibrated boundary: its underscore response weakens
slowly with document position and is stronger after a space-prefixed NAME.
Chat, thinking, and tool-response delimiters have their own small responses.
All state resets when the document changes.
"""
import math

READS = ()

# These are literal structural delimiters, not words about thinking or tools.
DELIMITERS = {
    '<think>': -0.123,
    '</think>': 0.029,
    '<tool_response>': 0.063,
    '</tool_response>': -0.059,
    '<|endoftext|>': 0.026,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, capitals, position = '', 0, 0
    else:
        _, previous, capitals, position = carry
    token = prefix.token_strings[-1]
    spaced = bool(token) and token[0].isspace()
    value = 0.0005
    if capitals >= 2:
        if token.isupper():
            value += (0.034 + 0.0074 * capitals if spaced
                      else 0.0023 * capitals)
        elif token.strip().istitle():
            value -= (0.024 * capitals if spaced
                      else 0.040 + 0.022 * capitals)
        elif token.islower():
            value -= 0.0133 * capitals
        elif token and token.strip('_') == '':
            value -= 0.132 + 0.017 * capitals
        else:
            value += 0.017 - 0.009 * capitals
    if previous.strip() == 'NAME' and token == '_':
        value = -0.625 + 0.029 * math.log1p(position)
        if previous.startswith(' '):
            value -= 0.164
    if token in DELIMITERS:
        value = DELIMITERS[token]
    elif token == '<|im_start|>':
        value = -0.139 if position == 0 else 0.030
    elif token == '<|im_end|>' and position == 0:
        value = -0.220
    if token == '<|endoftext|>' and position == 0:
        value = 0.113
    capitals = (min(12, capitals + sum(c.isupper() for c in token))
                if token.isupper() else 0)
    return (doc, token, capitals, position + 1), float(value)

