"""A negative response to quoted-string endings, especially code-like literals.

Quotes joined to colons, commas or closing brackets are stronger than quotes in
ordinary prose. A short, unspaced quoted span and a code delimiter before its
opening quote strengthen the response. Escaping, newlines and an immediately
following opening quote alter it. A bare equals sign has a smaller response.
The state remembers quote boundaries and whitespace, not the words themselves.
"""
READS = ()


def quote_ending(s, previous, distance, phrase, code):
    if any(c.isalnum() for c in s):
        return 0.0
    q = '"' if '"' in s else "'"
    if q not in s or q * 2 in s:
        return 0.0
    before, rest = s.split(q, 1)
    if any(c in before for c in '([{='):
        return 0.0
    if any(c not in '\\!?;:}. \t' for c in before):
        return 0.0
    spaced = previous.startswith((' ', '\t', '\n'))
    punct = not previous or not previous[-1].isalnum()
    single = q == "'"
    escaped = s.startswith('\\')
    prefixed = s[0] not in "'\"\\"
    if not rest:
        if before and before != '\\':
            return 0.0
        if escaped:
            return -0.91 + 0.49*phrase - 0.03*spaced + 0.23*punct - 0.31*code
        if single:
            return -1.38 + 1.09*phrase + 0.33*spaced + 0.10*punct - 0.83*code
        return -0.89 + 0.39*phrase + 0.20*spaced + 0.57*punct - 0.62*code
    if '\n' in rest or '\r' in rest:
        return -0.7 + 0.5*prefixed
    if rest.startswith(':'):
        if q in rest:
            return -0.76
        return (-2.60 + 0.28*(distance > 2) + 0.32*escaped
                + 0.40*spaced + 0.85*phrase - 0.19*code)
    if rest.startswith(','):
        if q in rest:
            return -0.43
        digit = bool(previous and previous[-1].isdigit())
        return (-1.12 + 0.12*(distance > 2) + 0.25*escaped
                + 0.45*spaced + 0.20*phrase + 0.19*digit - 0.68*code)
    if rest.startswith(')'):
        if ';' in rest or ',' in rest:
            return -0.85
        return -1.5 if '->' in rest or '.' in rest else -0.7 - 0.7*code
    if rest.startswith(']'):
        return -1.1 if ',' in rest or ')' in rest or q in rest else -1.8
    if rest.startswith('.'):
        return -0.6 + 0.1*spaced + 0.3*phrase
    if rest.startswith('\\'):
        return -1.0 if escaped or single else 0.0
    return -0.9 + 0.8*prefixed


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, 0, {})
    _, previous, position, spaces, quotes = carry
    s = prefix.token_strings[-1]
    value = 0.0
    if s.strip() == '=':
        value = -0.27 if s.startswith(' ') else -0.20
    elif '"' in s or "'" in s:
        q = '"' if '"' in s else "'"
        start, old_spaces, code = quotes.get(q, (-1000, -1000, False))
        value = quote_ending(s, previous, position-start, spaces > old_spaces, code)
    spaces += sum(c.isspace() for c in s)
    for q in ('"', "'"):
        if q in s:
            before = s.split(q, 1)[0].replace('\\', '').rstrip()
            before = before or previous.rstrip()
            code = bool(before and (before[-1] in '([{=,:'
                        or before.endswith(('(f', '(r', '(b'))))
            quotes[q] = (position, spaces, code)
    return (doc, s, position+1, spaces, quotes), float(value)

