    act = -0.3 if s == " =" else (-0.2 if s == "=" else 0.0)
    for i, c in enumerate(s):
        if c not in QUOTES:
            continue
        before = s[i - 1] if i > 0 else None
        after = s[i + 1] if i + 1 < len(s) else None
        if c == "'" and after is not None and after.isalpha():
            continue  # contraction such as 's or 't
        if c == '"' and before in {".", "!", "?"} and after in {None, "\n"}:
