        elif after is None and before in OPEN_BEFORE:
            closes = False  # quote just after a space or bracket opens a string
        elif after is None:
            closes = carry["open"] == c  # bare quote: closes if a string is open
        else:
            closes = False
        if closes:
            if after == ":":
                act = -2.4
            elif after in {",", ")", "]"}:
                act = -1.5
            else:
                act = -0.8
            if "\n" in s or ";" in s:
                act = -0.7
            if i + 2 < len(s) and s[i + 2] in QUOTES:
                act = -0.6  # closes one string and opens another, as in ":" or ","
