                act *= 0.5  # long quotation
            carry["open"] = None
            carry["text"] = ""
        else:
            carry["open"] = c
            carry["text"] = ""
    if carry["open"] is not None and not any(q in s for q in QUOTES):
        carry["text"] += s
    if "\n" in s:
        carry["open"] = None
    return carry, act

