"""Predict punctuation signals around assignments and quoted fields."""

READS = ()


def quoted_boundary(token):
    # A quote followed by a separator often closes a key or string.
    for quote in ('"', "'"):
        if token.count(quote) != 1:
            continue
        at = token.index(quote)
        if token[:at].rstrip().endswith("="):
            continue
        rest = token[at + 1:]
        if not rest:
            continue
        following = rest[0]
        if following == ":" and at > 0:
            continue
        values = {
            ":": -2.65,
            ",": -1.55,
            ")": -1.3,
            "]": -2.0,
            "}": -0.9,
            ".": -1.7,
            ";": -0.8,
            "\n": -0.75,
        }
        if following not in values:
            continue
        if "\n" in rest[1:]:
            if following == ",":
                return -0.72
            if following == ":":
                return -1.1
            if following == ")":
                return -0.9
        return values[following]

    # Tokens made only of quote and escape marks tend to be string boundaries.
    if (
        any(quote in token for quote in ('"', "'"))
        and not any(char.isspace() for char in token)
        and all(char in "\\'\"" for char in token)
    ):
        return -0.65
    return None


def assignment_mark(token):
    for at, char in enumerate(token):
        if char != "=":
            continue
        before = token[at - 1] if at else ""
        after = token[at + 1] if at + 1 < len(token) else ""
        if after in ("=", "\"", "'"):
            continue
        if before in ("=", "!", "<", ">") or after == "<":
            continue
        if after == ">":
            return -0.1
        if before and before in "+-*/%&|^":
            return -0.13
        if before == ":":
            return -0.07
        return -0.28
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]

    value = quoted_boundary(token)
    if value is None:
        value = assignment_mark(token)
    if value is None and "@" in token:
        value = 1.5 if token.startswith("}") else 0.2
    if value is None and token == "s" and tail.endswith("%"):
        value = 1.0
    if value is None and "|" in token and tail.endswith("\\"):
        value = 0.9
    if value is None and token == "}":
        value = 0.05
    if value is None:
        value = 0.0

    return (doc, (tail + token)[-32:]), float(value)

