EDGES = string.whitespace + string.punctuation
FUNCTION_DERIVATIVES = {
    'functional': 2.1, 'functionality': 1.7, 'functionalities': 1.3,
    'functioning': 3.8, 'malfunction': 2.85,
    'dysfunction': 2.0, 'dysfunctional': 2.0,
