             'abstract', 'partial', 'sealed'}


def lexical(token, word):
    w = word.lower()
    spaced = token.startswith(' ')
    if w in {'function', 'functions'}:
        if w == 'functions':
            if token.startswith('-'):
                return 6.0
            if token.startswith('/'):
                return 3.6
