        return 3.3
    if word.endswith('関数'):
        return 4.7
    if word.endswith('功能'):
        return 1.9
    if word == '함수':
        return 3.0
    if word in {'函', '関', '함'}:
        return 1.2
    if w in {'fun', 'func', 'fn'}:
        return {'fun': 1.2, 'func': 1.6 if spaced else 1.9, 'fn': 0.9}[w]
    if w == 'obj':
        return 0.4
    if w in {'string', 'object', 'strings', 'objects'}:
        return 0.75 if w.endswith('s') else 0.9
    if w in {'class', 'classes'}:
        return 1.15 if word[0].isupper() else 0.65
    if w in {'array', 'arrays'}:
        return 0.55
    if w in {'def', 'const', 'column', 'columns'}:
        return 0.72
    if w == 'arguments':
        return 0.35 if spaced else 0.75
    if w in {'frac', 'polynomial', 'polynomials'}:
        return 0.8
    if w == 'method':
        return 0.6 if word[0].isupper() else 0.24
    if w == 'command':
        return 0.24 if spaced else 0.37
    if w == 'ynomials':
