    token = prefix.token_strings[-1]
    word = token.strip(EDGES)
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else None
    value = lexical(token, word)
    # A byte-split character must be read in the decoded text, not alone.
    if '\ufffd' in word and word.endswith(('数', '能')):
        text = prefix.text_prefixes[-1]
        if text.endswith(('函数', '関数')):
            value = 4.7
        elif text.endswith('機能'):
            value = 1.3
    if token == ' class' and previous in MODIFIERS:
        value = 0.17
    if word.lower() == 'of' and previous in {'function', 'functions'}:
        value = 1.4
    return (doc, word.lower()), float(value)

