"""Layer-0 MLP down-projection, hidden unit 4316: a "function" detector.

The unit writes a strong signal into the residual stream on the word "function"
as a token: " function", "function", "(function", " Function", " functions",
" functioning" (about 4-6). The same idea in other languages gives a
medium signal ("функци", "Funktion", "fonction", "função", "함수", "功能").
Shorter stems "func", "fun", "fn" give a weaker signal (about 1-2), and
"functional" / "functionality" about 2. Programming nouns and keywords
("string", "object", "class", "def", "const", "array", "method", "column")
give a weak signal (about 0.8). Every other token gives 0.

The program reads only the newest token of the prefix; it does not use
context. Values are the average activations measured on training text.
"""

READS = ()

FUNCTION = {"function", "functions", "functioning"}
FOREIGN_FUNCTION = {"функци", "ункци", "funktion", "fonction", "função", "함수", "功能"}
FUNCTIONAL = {"functional", "functionality"}
STEMS = {"func": 1.8, "fun": 1.2, "fn": 1.0}
CODE_WORDS = {"string", "object", "class", "def", "const", "array", "method", "column",
              "arguments", "struct", "typescript", "frac", "fraction"}


def _word(token):
    # the word in a token: drop leading spaces, tabs, brackets, dots, slashes, underscores
    return token.lstrip(" \t([{.#/_\n\"'-").lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[prefix.position])
    if word in FUNCTION:
        value = 4.5
    elif word in FOREIGN_FUNCTION:
        value = 3.0
    elif word in FUNCTIONAL:
        value = 2.0
    elif word in STEMS:
        value = STEMS[word]
    elif word in CODE_WORDS:
        value = 0.8
    else:
        value = 0.0
    return carry, float(value)

