        _, position, previous, tail, digits = carry
        position += 1
    token = prefix.token_strings[-1]
    form = bracket_form(token)
    value = 0.0
    if form:
        opening, closing, offset, gain = form
        value = offset + gain * preceding_text(
            previous, tail, opening, closing, position, digits)
    digits = digits + len(token.strip()) if token.strip().isdecimal() else 0
    return (doc, position, token, (tail + token)[-160:], digits), float(value)

programs.haiku:
"""Closing brackets, signed by what they close.

Component layers.0.mlp.down_proj:4319 is a layer-0 MLP feature that fires on closing
brackets: ")", "]" and the fullwidth ")" (U+FF09). Its sign depends on the last character
of the text the bracket closes, the token just before it:

- It closes a word, as in "(musician)", "(Congress)" or "[index]": strongly positive.
  Brackets directly after a word are the big responses; "]" is a bit smaller than ")".
- It closes a number, as in "(1990)", "(2)" or "[3]": negative. "]" is more negative.
- Anything else, including brackets not preceded by a word or number, gives about 0.

A bracket with a comma attached ("),") gives a weaker positive response after a word.
Brackets with a newline, period or semicolon attached after a word give about 0, but
keep the negative response after a number. Positions at a document's start get 0.

The program is stateless: it reads only the newest token and the one before it.
"""

READS = ()

CLOSERS = ")]）"


def is_closer(token):
    return any(ch in CLOSERS for ch in token)


def is_bare(token):
    # A bare closer: only closing brackets, with at most a leading space or period.
    core = token[1:] if token[:1] in (" ", ".") else token
    return core != "" and all(ch in CLOSERS for ch in core)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if not is_closer(token) or len(prefix) < 2:
        return None, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0  # first token of a document: nothing before it
    square = "]" in token
    before = prefix.token_strings[-2][-1:]  # last character of the text it closes
    if before.isdigit():
        value = -1.0 if square else -0.6
    elif before.isalpha():
        if is_bare(token):
            value = 1.1 if square else 1.3
        elif token in ("),", "],"):
            value = 0.4
        else:
            value = 0.0
    else:
        value = 0.0
    return None, value


if __name__ == "__main__":
    # A quick look: print the value at each token of a short example.
    class Prefix:
        def __init__(self, tokens):
            self.token_strings = tokens
            self.document_ids = [0] * len(tokens)

        def __len__(self):
            return len(self.token_strings)

    tokens = ["The", " band", " (", "musician", ")", " played", " in", " 1990", " (", "see", " [", "3", "]", ")."]
    carry = None
    for i in range(len(tokens)):
        carry, value = step(carry, Prefix(tokens[: i + 1]), {})
        if value:
            print(f"{tokens[i]!r:>12} -> {value:+.2f}")

programs.sol:
"""A local detector for complements of beginnings, endpoints, and sources.

It responds most strongly to 'starts at', 'start with', and 'start by'.
The infinitive 'start to' instead gets a small negative response. Endings
and origins give weaker signals, as do boundary/state nouns and a few
causal-source constructions. These are word-class rules, not a parser:
only the current token and two preceding token strings are inspected.
Identifier separators and all-capital labels attenuate the response;
all memory resets at document boundaries.
"""
READS = ()

BEGINNINGS = {
    'start': 1.0, 'starts': 1.0, 'starting': .95, 'started': .85,
    'begin': .95, 'begins': 1.04, 'beginning': .90, 'began': .85,
    'begun': .80,
}
ENDINGS = {
    'end': .45, 'ends': .57, 'ending': .59, 'ended': .46,
    'conclude': .45, 'concludes': .54, 'concluding': .45,
    'concluded': .30, 'finish': .29, 'finishes': .29,
    'finishing': .29, 'finished': .19, 'completed': .14,
    'terminate': .48, 'terminates': .48, 'terminated': .35,
    'terminating': .40, 'stop': .22, 'stops': .22, 'stopped': .20,
}
ORIGINS = {
    'commence', 'commences', 'commenced', 'commencing',
    'initiate', 'initiated', 'origin', 'origins', 'originate',
    'originates', 'originating', 'originated', 'debut', 'debuted',
}
RELATIONS = {
    'at': 7.0, 'with': 6.05, 'by': 5.3, 'from': 4.1,
    'in': 3.4, 'on': 3.6, 'as': 2.8, 'when': 2.8,
    'here': 3.1, 'there': 2.1, 'now': 1.7,
    'out': 3.1, 'off': 3.8, 'over': 1.6,
    'to': -.65, 'of': -.10,
}
BOUNDARY_PROPERTIES = {
    'point': 3.6, 'points': 2.8, 'position': 2.4,
    'positions': 2.1, 'date': 3.0, 'time': 2.4, 'index': 2.0,
    'state': 2.0, 'states': 1.8, 'value': 2.0, 'values': 2.0,
    'site': 1.8, 'material': 4.0, 'materials': 3.0,
}
CAUSAL_SOURCES = {
    'caused', 'generated', 'induced', 'inspired', 'determined',
    'founded', 'driven', 'triggered', 'dominated',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry and carry[0] == doc else ()
    previous = history[-1] if history else ''
    raw = prefix.token_strings[-1].strip()
    token = raw.strip('_-').lower()
    strength = BEGINNINGS.get(previous, ENDINGS.get(previous, 0.0))
    value = strength * (RELATIONS.get(token, 0.0)
                        + BOUNDARY_PROPERTIES.get(token, 0.0))
    if previous in ENDINGS:
        if token in {'as', 'from', 'to'}:
            value = {'as': .2, 'from': .3, 'to': -.12}[token]
        elif token == 'by' and not previous.startswith('conclu'):
            value = 1.0
    if previous in ORIGINS:
        value = {'at': 2.3, 'with': 2.6, 'by': 2.5, 'from': 2.0,
                 'in': 1.5, 'on': 1.5, 'as': .4}.get(token, 0.0)
    if (not strength and len(history) == 2
            and previous in {'off', 'out', 'up', 'site'}):
        value = (.65 * BEGINNINGS.get(history[0], 0.0)
                 * RELATIONS.get(token, 0.0))
    if previous in {'center', 'centre', 'centered', 'centred', 'root', 'roots'}:
        value = {'at': 2.5, 'on': 1.1, 'in': .6}.get(token, value)
    if previous in CAUSAL_SOURCES and token == 'by':
        value = 1.0
    if previous == 'followed' and token == 'by':
        value = .53
    if (previous in {'derived', 'sourced', 'stemming', 'stemmed'}
            and token == 'from'):
        value = .65
    if previous == 'based' and token == 'in':
        value = .95
    if previous == 'born':
        value = {'at': 1.2, 'in': .77}.get(token, 0.0)
    if previous in {'initial', 'final', 'base', 'root', 'default', 'ground'}:
        if token in {
            'state', 'states', 'condition', 'conditions', 'position', 'positions'
        }:
            value = 2.0 if previous in {'initial', 'base'} else 1.2
        elif token in {
            'value', 'values', 'case', 'cases', 'class', 'material', 'materials'
        }:
            value = 1.8 if previous == 'base' else .6
        elif (previous == 'base'
              and token in {'station', 'stations', 'unit', 'units'}):
            value = 3.0
        elif previous == 'root' and token in {'cause', 'causes', 'stock', 'dir'}:
            value = 1.6
    if previous == 'exit' and token in {'code', 'status'}:
        value = 1.3
    # Identifier continuations and all-capital labels are weaker than prose.
    if raw.startswith(('_', '-')) and token in RELATIONS:
        value *= .5
    if history and carry[2]:
        value *= .4
    state = (doc, (history + (token.lstrip('.('),))[-2:], raw.isupper())
    return state, float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 4321: the "starting point" preposition.

It fires on the preposition or particle that comes right after a verb of starting,
beginning, ending or causing, as in "start WITH the", "starts AT 0", "begin BY
considering", "started FROM", "induced BY", "finished WITH", and on the word "code" in
"exit code". Its strength depends on the word: "at" and "with" strongest, then "by",
"from", "in", "on". Everywhere else it is near zero.

The program looks only at the current token and the one before it, and resets at each
document boundary.
"""

START_VERBS = {"start", "starts", "starting", "started", "begin", "begins", "beginning", "began"}
END_OR_CAUSE_VERBS = {
    "end", "ends", "ending", "ended", "finish", "finished", "completed", "complete",
    "induced", "caused", "initiated", "triggered", "driven", "inspired", "founded",
    "generated", "determined", "derived", "born",
}
# Strength after a start verb, measured on training text (activation units).
START_PREP_STRENGTH = {"at": 6.8, "with": 5.8, "by": 5.1, "from": 3.9, "in": 3.8, "on": 3.2}
POINT_WORDS = {"point": 3.7, "position": 2.5, "as": 2.8, "when": 2.8, "now": 1.6, "out": 2.7}

READS: tuple[str, ...] = ()


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    before = prefix.token_strings[-2].strip().lower()
    word = prefix.token_strings[-1].strip().lower()
    value = 0.0
    if before in START_VERBS:
        value = START_PREP_STRENGTH.get(word, POINT_WORDS.get(word, 0.0))
    elif before == "exit" and word == "code":
        value = 1.3
    elif before in END_OR_CAUSE_VERBS and word in {"with", "at", "by", "from", "in", "on"}:
        value = 1.0
    return carry, value

programs.sol:
"""Negative responses to H-like letters and acid/base chemistry.

Training examples show large negative activations on H, pH and hydroxide.

Capital H and Cyrillic Н are the main triggers. Latin H is stronger at a
document's start or near chemistry cues, and weaker inside acronyms and after
line breaks. Chemical symbols, hydrogen-bearing formula fragments, pH and
chemical words give related responses. The chemistry cue decays by 4% per
token and resets between documents. Other tokens are predicted as zero.
"""
READS = ()

ACIDS = {'acid', 'acids', 'acidic', 'alkali', 'alkaline', '酸', '碱'}
SALTS = {'sodium', 'carbonate', 'bicarbonate', 'chloride', 'hydroxide'}
SUBSTANCES = {
    'hydrogen', 'oxygen', 'proton', 'protons', 'alcohol', 'ethanol',
    'methanol', 'methane', 'glucose', 'sulfate', 'phosphate', 'vinegar',
    'detergent', 'saline', 'catalyst',
}
CUES = ACIDS | SALTS | SUBSTANCES | {
    'carbon', 'chlorine', 'molecule', 'molecules', 'chemistry', 'molar',
    'mol', 'mm',
}
FORMULAS = {
    'Na': -1.2,
    'NH': -1.3,
    'HC': -0.95,
    'HO': -0.9,
    'CO': -0.65,
    'SO': -0.65,
    'CH': -0.55,
    'SH': -0.45,
    'Cl': -0.65,
    'Ca': -0.25,
    'NO': -0.3,
    'PO': -0.3,
}
GLYPHS = {
    'Н': -1.38,
    'н': -0.28,
    'h': -0.13,
    'O': -0.2,
    'О': -0.2,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, chemistry = 0, '', 0.0
    else:
        _, position, previous, chemistry = carry
    text = prefix.token_strings[-1]
    s, before = text.strip(), previous.strip()
    word = s.lower()
    value = 0.0
    if s == 'H':
        if position == 0:
            value = -3.29 if text == s else -2.31
        else:
            value = -1.6 + 0.26 * (text != s)
            value -= 0.5 / (position + 1)**0.5 + 1.35 * chemistry
            value -= 0.45 * bool(before and before[-1].isdigit())
            value -= 0.5 * (before in {'C', 'O', 'N', 'S', 'Na', 'CO'})
            value += 0.6 * (text == s and before.isalpha()
                            and before.isupper() and len(before) > 1)
            value += 0.25 * ('\n' in previous) + 0.13 * before.endswith('.')
            value -= 1.25 * (text == 'H' and before == 'p')
    elif s.endswith('H') and not any(c.isalpha() for c in s[:-1]):
        value = -0.55 if s.startswith('_') else -0.9
    elif s == 'pH':
        value = -2.6 - 0.4 * chemistry
    elif s == 'OH':
        value = -2.3 - 1.0 * chemistry + 0.8 * (text != s)
        if text == s and before in {'Na', 'p'}:
            value = -4.4  # Sodium hydroxide (NaOH) or the pOH measure.
    elif s in FORMULAS:
        value = FORMULAS[s] - 0.7 * chemistry
        if s == 'Cl' and text != s:
            value += 0.35
        if position == 0 and text == 'Na':
            value = -3.23
    elif s in GLYPHS:
        value = GLYPHS[s] - 0.24 * (s == 'н' and text != s)
        if position == 0 and text == 'h':
            value = -1.18
        elif position == 0 and s in {'O', 'О'}:
            value = -0.57
    elif len(s) == 2 and s.isascii() and s.isalpha() and s.isupper():
        if s.endswith('H'):
            value = -1.05 if s == 'HH' else -0.55
        elif s.startswith('H'):
            value = -0.3
    elif word in ACIDS:
        value = -0.6 - 0.3 * chemistry
    elif word in SALTS or word.endswith('arbonate'):
        value = -0.7 - 0.3 * chemistry
    elif word in SUBSTANCES or word.endswith('anol'):
        value = -0.35 - 0.3 * chemistry
    elif word in {'base', 'bases', 'buffer', 'water', '水', 'solution'}:
        value = -0.17 - 0.2 * chemistry
    cue = word in CUES or s in {'pH', 'Na', 'Cl', 'OH'}
    chemistry = max(chemistry * 0.96, float(cue))
    return (doc, position + 1, text, chemistry), float(value)

programs.haiku:
"""Layer-0 MLP unit 4322 (down_proj): a "hydrogen H" detector.

This unit goes negative on the letter H when it is used as the chemical symbol for
hydrogen: the whole token "H" (or Cyrillic "Н"), most strongly in "pH". It is weaker on
other hydrogen and acid chemistry tokens ("OH", "-H", "CH", "HC", "Na", "acid", "sodium").
It is near zero everywhere else, including ordinary words that start with H ("Hello",
"House"). The program predicts the typical activation for each class of token, looking
only at the token being predicted.
"""

READS = ()

# Typical activation (in the component's own units) for each class of token.
BARE_H = {"H", "Н"}                       # the symbol H as a whole token
PH = {"pH"}                               # "pH" is the strongest case
HYDROXIDE = {"OH", "HO", "oh", "Ho"}      # hydroxide and similar
H_FORMULA = {"-H", ".H", "(H", "/H", "CH", "NH", "SH", "HC", "GH", "NO", "SO", "CO", "Na", "Cl"}
ACID_WORDS = {"acid", "acids", "acidic", "sodium", "base", "bases", "hydrogen", "hydro",
              "carbonate", "sulfate", "proton"}
LOWER_H = {"h", "н"}                      # lowercase h is only faintly negative

VALUE = {}
for token in BARE_H:
    VALUE[token] = -1.45
for token in PH:
    VALUE[token] = -2.9
for token in HYDROXIDE:
    VALUE[token] = -1.0
for token in H_FORMULA:
    VALUE[token] = -0.8
for token in ACID_WORDS:
    VALUE[token] = -0.5
for token in LOWER_H:
    VALUE[token] = -0.2


def step(carry, prefix, upstream):
    """The activation at this position: the class value of the token just read, else 0."""
    token = prefix.token_strings[-1].strip()
    return carry, float(VALUE.get(token, 0.0))

