"""Approximate a multilingual sibilant-spelling response.

The training examples favor isolated ш/š and short Cyrillic ш syllables.
This rule gives those large values, related sibilants smaller values, and
English sh/solution fragments weak values with common-word exceptions.
Longer fragments usually dilute the response. Split Unicode letters are
recovered from the decoded prefix; two identifiable UTF-8 word-start lead
bytes get provisional values. Small token-specific/context effects are omitted.
"""
READS = ()


def spelling_value(token):
    s = token.strip().lower()
    n = len(s)
    if not s:
        return 0.0
    if 'ш' in s:
        if s == 'ш':
            if token.strip().isupper():
                return 6.7 if token.startswith(' ') else 7.7
            return 6.2
        if n > 1 and token.strip().isupper():
            return 0.1
        if n == 2 and s.endswith('ш'):
            return 6.6 if s[0] in 'ае' else 5.6 if s[0] == 'и' else 4.7
        if s == 'реш':
            return 6.2 if token.startswith(' ') else 4.5
        if s == 'наш':
            return 5.2
        if s == 'ваш':
            return 3.1
        if s.startswith('решени'):
            return 2.8
        if s == 'ушки':
            return 2.7
        if s == 'больш':
            return 2.8
        if s.endswith('шь'):
            return 1.3 if s == 'ешь' else 0.5 if s == 'ишь' else 0.0
        if s.startswith('ш'):
            if n == 2:
                return 4.5 if s[1] == 'и' else 3.6 if s[1] == 'а' else 2.9
            if s.startswith(('шен', 'шие')):
                return 3.5
            return 2.6 if n <= 4 else 1.0
        return 3.0 if n == 3 else 1.3 if n <= 5 else 0.3
    if 'щ' in s:
        if s in ('ещ', 'ящ', 'ща'):
            return 0.6
        return 1.65 if n <= 2 else 1.0 if n <= 3 else 0.3
    if 'ж' in s:
        return 0.7 if n <= 3 else 0.5 if s.endswith('ж') else 0.0
    if 'ش' in s:
        return 0.45 if n <= 3 else 0.15
    if 'š' in s:
        if n == 1:
            if token.strip().isupper():
                return 6.7
            return 5.7 if token.startswith(' ') else 5.2
        return 3.3 if n == 2 else 1.0
    if 'ş' in s:
        return 2.0 if n == 1 else 0.6 if n <= 3 else 0.2
    if 'ș' in s:
        return 2.4 if n == 1 else 0.5
    if 'ž' in s:
        return 0.75 if n == 1 else 0.5 if n == 2 else 0.0
    if 'sz' in s:
        return 2.5 if s == 'ysz' else 0.75 if n <= 3 else 0.3
    if s == '什':
        return 3.5
    if 'solution' in s:
        return 0.75
    if 'sh' in s:
        if s.startswith(('should', 'show')) and not s.startswith('shower'):
            return 0.0
        if s in ('she', 'shall'):
            return 0.0
        if s.startswith(('shape', 'short')):
            return -0.15
        if s in ('share', 'shared'):
            return 0.2
        if s in ('cash', 'fish', 'fresh'):
            return -0.1
        if s == 'shift':
            return 0.0
        if s.startswith(('sho', 'shu', 'shr')):
            return 0.7
        if s in ('esh', 'osh', 'mesh', 'resh'):
            return 0.8
        return 0.35 if n <= 5 else 0.2
    return 0.0


# These vocabulary entries are UTF-8 lead bytes, not whole characters.
# The first begins a Latin Extended-A character (including Š, š, ſ, Ž).
LATIN_EXTENDED_WORD_LEAD = 25917  # b" \xc5"
CYRILLIC_WORD_LEAD = 8839        # b" \xd1"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if '�' in token:
        if prefix.token_ids[-1] == LATIN_EXTENDED_WORD_LEAD:
            return None, 1.58
        if prefix.token_ids[-1] == CYRILLIC_WORD_LEAD:
            return None, 0.95
        # Decode the completed character rather than the continuation byte alone.
        same_document = (len(prefix.token_ids) > 1 and
                         prefix.document_ids[-1] == prefix.document_ids[-2])
        last = prefix.text_prefixes[-1][-1:] if same_document else '�'
