"""A lexical signal for persistent and ongoing states.

Strong responses mark uninterrupted duration, habitual recurrence, and 'been'.
Chinese continuity expressions and Japanese progressive endings also respond.
Three-token context strengthens 'always been', weakens modal perfect aspect,
and detects 'continues to' and 'no longer'. This is lexical, not a semantic
truth test: even 'inconsistent' responds. Unrecognized tokens score zero.
Memory resets at document boundaries.
"""
READS = ()

# Duration, recurrence, and continuing change; scores are fitted amplitudes.
WORDS = {
    'continuous': 2.85, 'continuously': 3.3, 'continual': 2.65,
    'continually': 2.6, 'ongoing': 3.0, 'relentless': 2.05,
    'constantly': 1.8, 'lifelong': 1.8, 'persistent': 1.5,
    'longstanding': 1.5, 'consistently': 1.5, 'steadily': 1.5,
    'always': 1.3, 'consistent': 1.3, 'perpetual': 1.1,
    'repeatedly': 1.1, 'endless': 1.05, 'uninterrupted': 1.05,
    'steady': 0.8, 'continuity': 0.8, 'throughout': 0.8,
    'still': 0.75, 'consistency': 0.75, 'inconsistent': 0.75,
    'gradually': 0.75, 'evolving': 0.7, 'slowly': 0.65,
    'constant': 0.6, 'increasing': 0.56, 'growing': 0.46,
    # Habitual frequency words in other languages; French 'been'.
    'toujours': 1.2, 'siempre': 1.17, 'sempre': 0.97,
    'всегда': 0.97, 'постоянно': 1.15, 'été': 0.56,
}
MODALS = {'would', 'could', 'should', 'may', 'might', 'must'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ()
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev = recent[-1] if recent else ''
    value = WORDS.get(word, 0.0)
    if word == 'been':
        value = 1.25
        if prev == 'has':
            value = 1.47
        elif prev in {'have', 'had'}:
            value = 1.1
        elif prev == 'having':
            value = 0.87
        elif prev in {'not', 'yet', 'previously', 'already'}:
            value = 1.0
        if any(w in MODALS for w in recent):
            value -= 0.35
        if 'always' in recent[-2:]:
            value = 2.66
        elif prev == 'long':
            value = 1.83
    elif word == 'always':
        if prev in {'has', 'have', 'was', "'s", '’s', "'ve", '’ve'}:
            value = 1.6
        elif prev in {'not', 'almost'}:
            value = 0.93
        elif prev == 'can':
            value = 0.74
    elif word == 'to' and prev in {'continue', 'continues', 'continued', 'continuing'}:
        value = 1.0
    elif word == 'be' and prev == 'always':
        value = 0.66
    elif word == 'longer' and prev == 'no':
        value = 0.58
    # Chinese: all along, unceasing, and continuous duration.
    if '一直' in word:
        value = 5.75 if word.endswith('一直') else 4.75
        if word.endswith('到'):  # 'all the way to' rather than an ongoing state.
            value = 0.63
    elif '不断' in word:
        value = 3.64 if word == '不断' else 3.1
    elif '不斷' in word:
        value = 2.75
    elif '持续' in word:
        value = 0.32 if word.startswith('可') else 2.28
    elif '持續' in word:
        value = 1.82
    elif word in {'始终', '不间断'}:
        value = 2.6
    elif word in {'不停', '一路', '越来越'}:
        value = 1.7
    elif word in {'连续', '坚持', '每年', '逐渐', '逐步', '慢慢'}:
        value = 1.15
    elif word in {'依然', '仍然', '仍', '长期', '依旧'}:
        value = 0.85
    # Japanese: throughout/always, continuing, and progressive/resultative forms.
    elif word == 'ずっと':
        value = 2.53
    elif word in {'いつも', '常に', '続け', '続ける', '続けて'}:
        value = 1.0
    elif word in {'ている', 'している', 'いている', 'をしている'}:
        value = 0.6
    elif word in {'っている', 'しています'}:
        value = 0.4
    # Unspaced lower-case forms have a weaker measured response.
    if word in {'always', 'been', 'continuous', 'consistent'} and raw == word:
        value *= 0.8
    return (doc, (recent + (word,))[-3:]), float(value)

