"""Recognize a sparse lexical feature for persistence and continuity.

The component is usually quiet, but rises on words that express an ongoing,
repeated, or sustained state. Its strongest recurring cue is the perfect
auxiliary "been"; duration and cohesion vocabulary gives a smaller response.
"""

READS = ()

BEEN = {"been"}
REPEATED = {"always", "constantly", "steadily"}
SUSTAINED = {
    "constant", "throughout", "still", "slowly", "timeless",
    "ongoing", "continue", "continues", "continued", "continuing",
    "cohesive", "consistency", "consistent", "ingrained",
    "留存", "っている", "いている", "ている", "一緒",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in BEEN:
        return None, 1.20
    if word in REPEATED:
        values = {"always": 1.27, "constantly": 1.71, "steadily": 2.02}
        return None, values[word]
    if word in SUSTAINED:
        values = {
            "constant": 0.79, "throughout": 0.86, "still": 0.76,
            "slowly": 0.57, "timeless": 0.46, "ongoing": 0.81,
            "cohesive": 0.40, "consistency": 0.90,
            "留存": 0.45, "っている": 0.48, "いている": 0.65,
            "ている": 0.62, "一緒": 0.53,
        }
        return None, values.get(word, 0.5)
    return None, 0.00128

