"""Detect D/d as a letter or a very short token fragment.

Capital D gives the strongest negative response. Punctuation-attached letters
and consonant+D abbreviations are weaker. A lone d appended to a word, or
a capital D appended to an all-capital word, is attenuated. Vowel+d endings and
apostrophe-d contractions are mostly excluded, rather than matching every d
inside a word. Several other scripts' d letters and the Markdown .md extension
also get negative responses. All other tokens predict zero. The strengths
approximate averages on random training rows; the two word-boundary flags
reset at document changes.
"""
READS = ()
VOWELS = frozenset('aeiouAEIOU')
D_LETTERS = {
    'ด': -0.82,  # Thai do dek
    'د': -0.46,  # Arabic dal
    'Д': -0.35,  # Cyrillic capital de
    'д': -0.02,  # Cyrillic lowercase de
    'δ': -0.07,  # Greek lowercase delta
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        in_word, all_upper = False, False
    else:
        _, in_word, all_upper = carry
    token = prefix.token_strings[-1]
    text = token.strip()
    letters = ''.join(c for c in text if c.isalpha())
    spaced = token.startswith(' ')
    attached = in_word and token == text
    value = 0.0
    if text in D_LETTERS:
        value = D_LETTERS[text]
        if spaced and text != 'ด':
            value -= 0.25
    elif letters == 'D':
        if text != 'D':
            value = -2.0
        elif spaced:
            value = -2.41
        else:
            value = -1.60 if attached and all_upper else -2.60
    elif letters == 'd':
        if text.startswith(("'", '’')):
            value = -0.09
        elif text == 'd':
            value = -0.88 if attached else -1.20
        else:
            value = -1.27
    elif len(text) == 2 and text.isascii() and text.isalpha():
        first, last = text
        if last == 'D':
            value = -0.65 if first in VOWELS else -1.75
        elif last == 'd' and first.islower():
            if first == 'a':
                value = -0.58 if spaced else -0.16
            elif first not in VOWELS:
                # Common word-ending clusters: ld, nd, rd.
                value = -0.35 if first in 'lnr' else -0.80
    elif text == '.md':  # Markdown filename extension.
        value = -1.14
    for char in token:
        if char.isalpha():
            all_upper = char.isupper() and (all_upper or not in_word)
            in_word = True
        else:
            in_word, all_upper = False, False
    return (document, in_word, all_upper), value

"""Negative indication/representation signal, strongest for the CJK character 示.

Current-token word forms supply almost all predictions. The character 示 means
'show'; 表示 means 'express/indicate'. English 'indicated' is much stronger than
'shown'. Related multilingual stems also respond. Split compounds such as
標示 (label) and 掲示 (post a notice) adjust the standalone 示 signal. A few
following articles/prepositions inherit a small signal. Values approximate
training averages; weak unrelated token biases and longer context are omitted.
"""

READS = ()

CJK_CUES = {
    '示': -3.05,
    '表示': -2.16,
    '提示': -1.77,
    '标识': -1.36,
    '所示': -1.30,
    '指示': -1.23,
    '示范': -1.20,
    '示例': -1.06,
    '顯示': -1.06,
    '揭示': -1.03,
    '演示': -0.86,
    '显示': -0.81,
    '释': -0.56,
    '釋': -0.36,
}
VERBS = {'indicate', 'indicates', 'indicated', 'indicating'}
NOUNS = {'indication', 'indications', 'indicative'}


def lexical_value(word):
    if word in CJK_CUES:
        return CJK_CUES[word]
    if word.endswith('表示'):
        return -1.70
    if '示' in word:
        return -0.65 if len(word) == 2 else -0.45
    if word in {'解释', '解釋', '表述'}:
        return -0.29
    if word in {'说明', '說明'}:
        return -0.22
    if word in {'表态', '表明', '告诉记者', '标志'}:
        return -0.58
    if word in {'标记', '指出', '告知'}:
        return -0.32
    word = word.lower()
    if word in VERBS:
        return -0.86 if word == 'indicated' else -0.79
    if word in NOUNS:
        return -0.45
    if word in {'indicator', 'indicators'}:
        return -0.30
    if word in {'representation', 'representations'}:
        return -0.49
    if word in {'represent', 'represented'}:
        return -0.22
    if word in {'represents', 'representing'}:
        return -0.09
    if word in {'identifier', 'identifiers'}:
        return -0.38
    if word.startswith('illustr'):
        return -0.36 if word == 'illustrated' else -0.25
    if word.startswith('demonstr'):
        return -0.35 if 'ation' in word else -0.25
    if word in {'suggest', 'suggests', 'suggesting', 'suggested'}:
        return -0.29 if word == 'suggested' else -0.18
    if word in {'instruction', 'instructions', 'direction', 'directions',
                'shown', 'revealed', 'hinted', 'depicted', 'denotes', 'hint'}:
        return -0.22
