    if word == 'показ':
        return -1.00
    if word in {'ображ', 'göster'}:
        return -0.79
    if word in {'представ', 'indic', 'représ', '나타', 'biểu', 'แสดง'}:
        return -0.58
    if word in {'указ', 'указан', 'представлен', 'indica',
                'mostr', 'mostrar', 'chỉ'}:
        return -0.40
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == document
    previous = carry[1] if same_document else ''
    word = prefix.token_strings[-1].strip()
    lower = word.lower()
    value = lexical_value(word)
    if word == '示' and same_document:
        # Decode the rare compound ending together: 掲 may span byte tokens.
        ending = prefix.text_prefixes[-1][-2:]
        if ending in {'标示', '標示'}:
            value = -4.10
        elif ending == '掲示':
            value = -2.50
        elif ending == '表示':
            value = -2.94
        elif ending == '開示':
            value = -2.83
    if previous in VERBS:
        if lower in {'a', 'an'}:
            value = -0.22
        elif lower in {'the', 'to'}:
            value = -0.18
    elif previous in NOUNS and lower == 'of':
        value = -0.27
    elif previous in {'representation', 'representations'} and lower == 'of':
        value = -0.10
    elif previous == 'ind' and lower in {'icate', 'icated'}:
        value = -0.40 if lower == 'icate' else -0.50
    return (document, lower), value

