"""Mark words that say that something is indicated or represented."""

import re

READS = ()

_ENGLISH = re.compile(
    r"(?:^|[^a-z])(?:indicat(?:e|es|ed|ing|ion|ions|ive|or|ors)?|"
    r"indic|represent(?:ation|ations|ed|ing|s)?)$",
    re.IGNORECASE,
)
_RUSSIAN = {"показ": -1.01, "указ": -0.48}
_CHINESE = {
    "显示": -0.62,
    "标识": -1.04,
    "表示": -1.50,
    "展示": -0.58,
    "表态": -0.68,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = (tail + token)[-48:]
    lower = text.lower()

    value = 0.0
    if _ENGLISH.search(text):
        value = -0.54 if lower.endswith(("indic", "representation", "representations")) else -0.78
    else:
        for word, activation in _RUSSIAN.items():
            if text.endswith(word):
                value = activation
                break
        for word, activation in _CHINESE.items():
            if text.endswith(word):
                value = activation
                break
        if text.endswith("나타"):
            value = -0.68

    return (doc, text), value

