READS = ()
RAISE = {'raise', 'raises', 'raised', 'raising'}
RISE = {'rise', 'rises', 'rising', 'risen', 'rose',
        'arise', 'arises', 'arising', 'arisen', 'arose'}
ARTICLES = {'the', 'a', 'an'}
POSSESSIVES = {'his', 'her', 'their', 'our', 'your', 'my', 'its'}
UPWARD_VERBS = {'go', 'goes', 'going', 'went', 'bring', 'brings',
                'bringing', 'brought'}
