    if bare in RAISE or word == 'aising':
        if word.startswith(('.', '_')):
            return -6.0 if bare == 'raise' else -3.6
        if not raw[:1].isspace() and previous.rstrip().lower().endswith('app'):
            return -0.3
        if not raw[:1].isspace() and previous.rstrip().lower().endswith('p'):
            return -2.8
        if word == 'aising':
            return -6.8
        if not raw[:1].isspace() or raw.strip()[:1].isupper():
            return -5.7
        return -6.3 if bare in {'raised', 'raises'} else -6.7
    if word in {'fundraising', 'fundraiser', 'fundraisers'}:
        return -2.0
    if word == '-ra':
        return -3.1
