    value = chinese(z, previous, age < 12)
    if (z and all('ァ' <= c <= 'ヿ' or c == '�' for c in z)
            and any('ァ' <= c <= 'ヿ' for c in z)):
        value = japanese(z)
        if len(z) > 2:
            value -= 0.20
    elif z in '트드스즈크프브' and len(z) == 1:
        value = 0.90
    elif z and all('가' <= c <= '힣' for c in z):
        value = 0.0
        if len(z) == 1:
            code = ord(z) - 0xAC00
            final, vowel = code % 28, (code // 28) % 21
            if final == 0:
                value = 0.15
            elif final in (16, 21) and vowel == 20:
                value = 0.30  # loanword -im/-ing syllable
    elif z == '์':
        value = 0.65  # Thai consonant-silencing mark
    elif len(z) == 1 and z in 'ทตส':
        value = 0.33
    elif z in {'·', '・'}:
        value = 0.15
        if previous and previous[-1] in NAME_ALPHABET:
            value = 0.90
    elif s == '<tool_call>':
        value = 0.21
    elif s == '</tool_call>':
        value = 0.35
    elif s == '</tool_response>':
        value = -0.11
    if any('ぁ' <= c <= 'ゖ' for c in s):
        age = 0
    return (doc, s, age), float(value)

