    elif not text.isascii() or not text.isalpha():
        value = 0.0
    elif word == 'sky':
        value = 3.5
    elif word == 'skies':
        value = 1.2
    elif word.startswith('sky') or word.endswith('sky'):
        value = 0.8
    elif word == 'sk':
        value = 0.65 if text[0].isupper() else 0.3
    elif word == 'sys':
        value = 1.25
    elif word == 'why':
        value = 0.7
    elif word == 'y':
        value = 1.2
        if raw == 'y' and previous:
            value = 0.98 if previous[-1].islower() else 1.5
            if previous[-1].isdigit():
                value = 1.2
        elif raw == 'Y' and previous and previous[-1].isupper():
            value = 0.9
    elif word == 'by':
        value = 1.35 if text == 'By' else 1.05
        if raw == ' by':
            value = 0.63 if previous.lower().endswith('ed') else 0.88
    elif word == 'my':
        value = 0.0 if boundary or text[0].isupper() else 0.2
    elif len(word) == 2 and word.endswith('y'):
        if word[0] == 'k':
            value = 1.7
            if raw == 'ky' and previous.lower().endswith('s'):
                value = 2.5
        elif word[0] in 'aeiou':
            value = 0.0 if word[0] == 'a' else 0.27
        elif word == 'xy':
            value = 0.5
        elif word in ('ly', 'ry', 'ty') and text.islower() and not boundary:
            value = 0.4 if word == 'ly' else 0.65
        else:
            value = 1.1 if boundary or text[0].isupper() else 0.9
        if raw == '.py':
            value = 0.84
    elif len(word) == 3 and word.endswith('y') and not boundary:
        common_ending = word.endswith(('ay', 'ey')) or word in ('ary', 'ity')
        value = 0.0 if common_ending else 0.25
    else:
        value = 0.0
    return None, float(value)

