"""A partial lexical predictor for 'this' and publicly discussed information.

It recognizes familiar word families about news, accusations, disclosure and
noteworthy reactions. Capitalization and spacing distinguish forms of 'this';
Previous-word rules distinguish prose 'public' from code, adjust definite topics,
and downweight 'about' after thinking/talking verbs.
Unlisted associations (including many names and fragments) are left at zero.
"""
from functools import lru_cache

READS = ()

# Word classes share a value; regular English endings are matched below.
GROUPS = {
    'scandal': (1.6, '''allegations scandal slander defamation notorious infamous
        sensational 谣言 謠言 丑闻 醜聞 诽谤 誹謗'''),
    'visibility': (1.21, '''publicity openly confidential confidentiality
        公开 公開 公然 公众 公眾 曝光 公表'''),
    'inquiry': (0.94, '''allegation alleged allegedly accusation controversy
        controversial rumor gossip investigate investigation investigative
        scrutiny conspiracy innocent unethical subpoena indictment affidavit
        投诉 投訴 涉嫌 调查 調查 調査 审查 審査 问责 噂'''),
    'news': (0.73, '''news newspaper journalist journalism journalistic reportedly
        reporter editorial headline famous celebrity reputation renowned
        新闻 新聞 报纸 報紙 记者 記者 ニュース'''),
    'strong_reaction': (1.42, 'hilarious ridiculous embarrassing bizarre'),
    'interest_humor': (0.72, '''interesting remarkable provocative fascinating
        intriguing entertaining funny humorous joke absurd laugh comedian
        comic 有趣 笑 笑话 笑話 奇葩'''),
    'information': (0.28, '''information informative info fact detail letter story
        statement document transcript report publish publication broadcast
        interview claim comment lie honest criticism complaint suspicion
        suspected admitted reveal expose matter concern media internet twitter
        facebook mainstream 信息 内容 內容 媒体 媒體 报道 報道 批评 批評'''),
    'evidence_access': (0.45, '''evidence factual truth testify testimony witness
        documented disclose disclosure revelation whistleblower confess
        secret privacy sensitive transparent transparency hidden surveillance
        真相 事实 事實 证据 證據 秘密 隐私 隱私'''),
    'incident': (0.87, 'incident 事件 案件'),
    'public_judgment': (0.97, '''misconduct inappropriate questionable misleading
        unfair racist hypocrisy'''),
}
WORDS = {word: (name, value)
         for name, (value, words) in GROUPS.items() for word in words.split()}
ARTICLES = {'the', 'a', 'an', 'this', 'that'}
THINK_TALK = {'think', 'thinking', 'thought', 'talk', 'talks', 'talked',
              'talking', 'worry', 'worried', 'worrying', 'to'}


@lru_cache(maxsize=8192)
def classify(token):
    surface = token.strip()
    word = surface.strip('(){}[]"\'`$._/').lower()
    if word == 'this':
        if surface.lower() != 'this':
            return 'reference', 0.60
        if surface == 'This':
            return 'reference', 0.87 if token[:1].isspace() else 0.94
        return 'reference', 0.74 if token[:1].isspace() else 0.61
    if word == 'public':
        return 'public', 0.70
    if word == 'publicly':
        return 'publicly', 1.64
    if word in {'about', 'regarding'}:
        return 'about', 0.25
    if word in {'这', '這', '此', 'この', 'これ', 'こんな'}:
        return 'reference', 0.40
    if word == '被':                    # Chinese passive marker
        return 'grammar', 0.61
    if word == '了':                    # Chinese completion marker
        return 'grammar', 0.21
    if word in {'的', 'の'}:            # Chinese/Japanese linking particles
        return 'grammar', -0.09
    roots = [word]
    if word.endswith('ies'):
        roots.append(word[:-3] + 'y')
    if word.endswith('s'):
        roots.append(word[:-1])
    if word.endswith('ed'):
        roots.extend((word[:-1], word[:-2]))
    if word.endswith('ing'):
        roots.extend((word[:-3], word[:-3] + 'e'))
    for root in roots:
        if root in WORDS:
            return WORDS[root]
    return 'background', 0.0


def adjust(name, token, previous):
    prev = previous.strip().lower()
    value = 0.0
    if name == 'public':
        if not previous.strip() or any(c in previous for c in '{};`'):
            value -= 0.69
    if name == 'about' and prev in THINK_TALK:
        value -= 0.27
    if name in {'news', 'inquiry', 'information', 'evidence_access'}:
        if prev in ARTICLES:
            value += 0.10
    if name in GROUPS and token.strip().isascii():
        if (token.strip().lower().endswith('s')
                and token.strip().lower() != 'news'):
            value += 0.09
        if not token[:1].isspace():
            value -= 0.11
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ''
    if len(prefix.token_ids) > 1 and (
            prefix.document_ids[-2] == prefix.document_ids[-1]):
        previous = prefix.token_strings[-2]
    name, value = classify(token)
    return None, float(value + adjust(name, token, previous))

