AHEAD = {'先行', '率先', '最先', '先后', '优先', '先把'}
BEFOREHAND = {'首先', '事先', '预先', '抢先', '先是'}
EARLIER = {'先前', '领先', '先进'}
ASIAN_WORDS = {
    '首': -0.64,
    '首要': -1.85,
    '第一': -0.9,
    '第一个': -1.2,
    '再': -0.73,
    '提前': -0.7,
    'まず': -2.02,
    'まずは': -1.62,
    'すでに': -0.78,
    '선': -2.1,
    '먼저': -3.3,
    '우선': -3.85,
    '仙': -1.3,  # Homophone of 先.
