    elif '先' in word:
        value = -2.4 if word.startswith('首先') else -2.7 / len(word)
    elif '已经' in word or '已經' in word:
        value = -2.08 / len(word)
    elif word == '早已':
        value = -1.27
    elif '已' in word:
        value = -0.9 / len(word)
    elif word == '선' and raw.startswith(' '):
        value = -3.1
    elif word in ASIAN_WORDS:
