        if word == 'First':
            value = -2.4 if raw.startswith(' ') else -2.08
        else:
            value = -1.85
            if prev in {'the', 'at'}:
                value = -1.72
            elif prev == 'very':
                value = -1.21
            elif prev in {'me', 'us', 'will'}:
