    elif bare == 'firstly':
        value = -3.25 if word == 'Firstly' else -2.22
    elif bare.startswith('first'):
        value = -0.95  # E.g. firstName, firstChild.
    elif bare == 'already':
        value = -1.65
        if prev in PERFECT:
            value = -2.6 if prev == 'have' else -2.8
        elif prev in {'had', "'t", '’t'}:
            value = -2.15
