"""Recognize temporal and form-description phrases, with opposite signs.

Most tokens contribute approximately zero. 'Time' is especially negative
in 'at the time' and 'long/short time'; 'form' is especially positive
when preceded by an article or a description of its shape. Some adjective-
hyphen compounds and 'reduced to' also receive positive responses. An 'of'
following time/form carries a weakened version of the noun's response.
Only two preceding tokens and the previous prediction are retained.
These rules approximate the prominent local patterns seen in training;
unrelated lexical responses are deliberately left unmodeled.
"""

READS = ()

DURATION = {'long', 'short'}
TIME_WEAK = {
    'over', 'every', 'each', 'next', 'last', 'this', 'and', 'to',
    'have', 'is', 'response', 'spare', 'by', 'for',
}
TIME_STRONG = {'any', 'at', 'hard', 'difficult', 'average', 'certain', 'later'}
FORM_DESCRIPTIONS = {
    'standard', 'normal', 'physical', 'functional', 'simplified',
    'expanded', 'reduced', 'closed', 'general',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, older, previous_value = '', '', 0.0
    else:
        _, previous, older, previous_value = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0

    if token == ' time':
        value = -0.23
        if previous == 'the':
            value = -0.65
            if older == 'at':
                value = -1.12
            elif older == 'within':
                value = -1.3
        elif previous in DURATION:
            value = -0.98
        elif previous in {'limited', 'present'}:
            value = -0.77
        elif previous in TIME_STRONG:
            value = -0.49
        elif previous == 'that':
            value = -0.41
        elif previous in TIME_WEAK:
            value = -0.06
    elif token in {' Time', '-time'}:
        value = -0.12
        if previous in DURATION:
            value = -0.73
        elif previous == 'full' and token == ' Time':
            value = -0.47
    elif token == 'Time':
        value = -0.06
    elif token == ' times':
        value = -0.11
    elif token == ' day':
        value = -0.08
        if previous == 'the':
            value = -0.24
        elif previous == 'present':
            value = -0.50

    if word in {'form', '-form'}:
        value = 0.15
        if token == ' form' or word == '-form':
            value = 0.26
            if previous == 'the':
                value = 0.72
            elif previous in FORM_DESCRIPTIONS:
                value = 0.97
            elif previous in {'pure', 'basic', 'native', 'simplest'}:
                value = 0.64
            elif previous in {'to', 'a', 'can', 'will', 'this', 'each', 'do'}:
                value = 0.11
        elif token in {' Form', 'Form'}:
            value = 0.22
    elif token == ' forms':
        value = 0.16
    elif token == ' formula':
        value = 0.15

    if token.startswith('-') and word not in {'-time', '-form', '-profile'}:
        if previous in {'low', 'high'}:
            value = 0.65 if len(word) <= 4 else 0.16
        elif previous in {'full', 'double'}:
            value = 0.45 if len(word) <= 3 else 0.05
    if token == ' to':
        if previous in {'reduced', 'reduces', 'decreased'}:
            value = 0.51
        elif previous == 'limited':
            value = 0.32
        elif previous == 'close':
            value = 0.19
    if token == ' of' and previous in {'time', 'form'}:
        value = 0.36 * previous_value - 0.075

    return (doc, word, previous, value), float(value)

programs.luna:
"""Mark statement-qualifying and connective words with a moderate value."""

READS = ()

MARKERS = frozenset({
    "also", "actually", "clearly", "course", "especially", "eventually",
    "fact", "least", "more", "not", "now", "possibly", "preferably",
    "probably", "usually", "unfortunately", "donc", "ainda", "ведь",
    "вообще", "также", "этом", "noch", "兼", "就", "很明显",
})


def _word(text):
    end = len(text)
    while end and not text[end - 1].isalpha():
        end -= 1
    start = end
    while start and text[start - 1].isalpha():
        start -= 1
    return text[start:end].lower()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = _word(token)
    doc = prefix.document_ids[-1]
    if carry is not None and token and token[0].isascii() and token[0].isalpha():
        old_doc, old_word = carry
        end = 0
        while end < len(token) and token[end].isalpha():
            end += 1
        if old_doc == doc and end == len(token):
            word = old_word + word
    next_carry = (doc, word if token and token[-1].isalpha() else "")
    if word in MARKERS:
        return next_carry, 0.75
    if len(word) > 4 and word.endswith("ly"):
        return next_carry, 0.4
    return next_carry, 0.0

programs.sol:
"""Approximate a digit-boundary signal, not a full number parser.

Single ASCII-digit tokens get negative values after ordinary number separators,
positive values when attached to letters, and little response after digits or
a decimal point. Whitespace, punctuation, and word classes refine the boundary;
smaller digit values usually have stronger responses. All other tokens get zero.
Only the preceding two token strings are remembered, resetting at each document.
"""
READS = ()

MONTHS = set(('january february march april may june july august september '
              'october november december').split())
REFERENCES = set('fig figure table section equation example chapter'.split())
FUNCTION_WORDS = set('to in by from on with over than and or'.split())
MATH_WORDS = {'mod', 'sqrt'}
# Year, month, day, 'to', ordinal marker, and 'at'.
CHINESE_NUMERIC_LINKS = set('年月日至第在')


def spaced_number(before):
    """First digit after one space: distinguish prose, lists, and arithmetic."""
    word = before.strip()
    if len(word) == 1 and word.isascii() and word.isdigit():
        return 0.05
    if before == ' ':
        return 0.22
    if before.isspace():
        return -0.56
    if word == '.':
        return -0.67 if before[0].isspace() else -0.14
    if any(c in word for c in '=<>'):
        if not before[0].isspace():
            return -0.60
        return -1.65 if len(word) > 1 else -1.15
    if word and word[-1] in '+-*/–−':
        return -1.14 if before[0].isspace() else -0.67
    if word and word[-1] in ',:;':
        return -0.72 if word == ';' else -1.01
    if word.replace('_', '').isalpha() and word.isascii():
        if word == 'a':
            return -0.55
        if len(word) == 1 or (len(word) <= 3 and word.isupper()):
            return -0.18
        if word.lower() in FUNCTION_WORDS:
            return -1.10
        if word.lower() in MONTHS:
            return -1.05
        if word.lower() in REFERENCES:
            return -0.32
        return -0.84 if before[0].isspace() else -0.59
    if word == ')':
        return -0.39
    if '\n' in before:
        return -0.29
    return -0.64 if before else -0.21


def digit_boundary(previous, before):
    p = previous.strip()
    if not previous:
        return 0.03
    if previous[-1:].isdigit():
        return 0.01
    if '\n' in previous or '\r' in previous:
        if p.endswith('.'):
            return 0.32
        return 0.07 if not p else -0.03
    if previous == ' ':
        return spaced_number(before)
    if previous.isspace():
        return -0.29
    if previous[-1:].isalpha():
        if p.lower() in MATH_WORDS or p.lower() == 'x':
            return 0.20
        if p.lower() == 'v':
            return 0.47
        if p in CHINESE_NUMERIC_LINKS:
            return -0.13
        if '\u4e00' <= previous[-1] <= '\u9fff':
            return 0.46
        return 0.76
    spaced = previous[0].isspace()
    if p == '.':
        return 0.81 if spaced else 0.04
    if p in ('-', '/'):
        if not spaced:
            return -1.51
        return -0.83 if p == '-' else -0.33
    if p in ('+', '=', '==', '===', '<', '>', '<=', '>=', '!=', '!=='):
        if p in ('<', '>'):
            return -0.30 if spaced else -0.58
        return -0.39 if spaced else -1.07
    if p in ('(', '[', '"', "'", '#'):
        if p in ('#', '"', "'"):
            return -0.40
        return -0.44 if spaced else -1.01
    if p in (',', ':', ';', '،'):
        return -0.08 if p == ';' else -0.74
    if p in ('_', '__'):
        return -0.30 if p == '__' else -0.71
    if p.endswith('^') or p.endswith('^{') or p.endswith('_{'):
        return -0.42
    if p in ('$', '$$', '\\('):
        return -0.20
    if p in ('√', '**'):
        return -0.10
    if p in (')', '?', '。'):
        return 0.55
    if p in ('，', '：'):
        return -0.05
    if p in ('£', '€', '¥', '₹'):
        return 0.20
    if p in ('–', '−'):
        return -0.14 if spaced else -0.86
    if p.endswith(('-', '/', '=', '*')):
        return -0.88
    return -0.52


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token) == 1 and '0' <= token <= '9':
        value = digit_boundary(previous, before)
        numeral = int(token)
        # Boundary strength tends to decline with the digit's numerical value.
        gain = 1.08 - (0.03 if value < 0 else 0.013) * numeral
        if numeral == 0:
            gain -= 0.035 if value < 0 else 0.04
        value *= gain
    return (doc, token, previous), value

"""Lexical responses, chiefly to Chinese 为 ('for/as/be') and its variants.

A standalone marker has a large negative response. Common compounds are
weaker, especially 'because' and 'why'; longer compounds dilute it further.
Japanese case/purpose markers, Korean case particles, and English behavior
words have smaller responses. These are spelling rules, not a claim that all
these expressions share one meaning. The constants approximate training
activations; unlisted spellings and most contextual variation are omitted.
A short text tail recognizes 'convert/define as' across token boundaries.
"""
READS = ()

# Traditional/older spellings of the Chinese markers used below.
CHINESE_SPELLINGS = str.maketrans('為爲認稱視變轉換義', '为为认称视变转换义')


def response(token, previous):
    s = token.strip()
    chinese = s.translate(CHINESE_SPELLINGS)
    if '为' in chinese:
        if chinese == '为':
            before = previous.translate(CHINESE_SPELLINGS)
            if before.endswith(('转换', '转化', '定义')):
                return -3.1
            if before.endswith('认'):
                return -2.5
            return -5.5
        if '为什' in chinese or '为何' in chinese:  # why
            return -0.3
        if '因为' in chinese:  # because
            return -0.65
        if any(w in chinese for w in ('认为', '作为', '为了')):
            # consider, act as, in order to
            return -1.4 * min(1.0, 2.5 / len(chinese))
        if '成为' in chinese:  # become
            return -1.95 * min(1.0, 2.25 / len(chinese))
        if '行为' in chinese:  # behavior
            return -2.4
        if any(w in chinese for w in ('称为', '视为', '变为', '改为')):
            return -2.4  # called/regarded/changed into
        if '为止' in chinese:  # until / so far
            return -1.6 if chinese == '为止' else 0.0
        return -2.3 if len(chinese) >= 4 else -4.0

    # Japanese particles at the end of a token are stronger than internal ones.
    if s.endswith('のが'):
        return -1.95
    if s.endswith('のですが'):
        return -1.1
    if s.endswith('ですが'):
        return -0.2
    if s.endswith('ますが'):
        return -0.5
    if s == 'だが':
        return -0.65
    if s.endswith('が'):
        return -1.03
    if s in ('それを', 'これを', 'ものを', '事を'):
        return -1.65
    if s.endswith('を'):
        return -0.85 if s == 'を' else -1.05
    if s in ('をして', 'をする', 'を行う'):
        return -0.75
    if 'が' in s or 'を' in s:
        return -0.18
    if 'ため' in s:  # purpose / sake
        return -0.65 if s == 'そのため' else -1.25
    if s in ('として', 'とした', 'にして'):
        return -0.6
    if s.startswith('とな'):  # become / turn into
        return -0.9

    if s.endswith(('을', '를')):  # Korean object particles
        return -1.2 if '것' in s else -0.43
    if s in ('이', '가'):  # Korean subject particles
        return -0.18
    english = s.strip('_.').lower()
    if english.startswith(('behavior', 'behaviour', 'behalf')):
        return -0.95
    if english.startswith('behav'):
        return -0.45
    if chinese in ('做', '作', '给', '給', '帮', '幫'):
        return -0.7  # do, give, help
    if chinese == '替':  # on behalf of / replace
        return -1.35
    if chinese in ('是', '也是', '就是', '还是', '不是'):
        return -0.23  # forms of 'is'
    if chinese in ('都是', '真是', '更是', '很是'):
        return -0.6  # emphatic forms of 'is'
    return -0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, start = '', prefix.position
    else:
        _, previous, start = carry
    token = prefix.token_strings[-1]
    tail = (previous + token)[-12:]
    if '\ufffd' in token:
        # Recover a completed byte-split character, without crossing documents.
        text = prefix.text_prefixes[-1]
        if start:
            text = text[len(prefix.text_prefixes[start - 1]):]
        tail = text[-12:]
        if text and text[-1] in '为為爲がを':
            token, previous = text[-1], text[-13:-1]
    return (doc, tail, start), response(token, previous)

programs.luna:
"""A lexical approximation to a sparse predication/role-marking signal.

Harvested responses point to Chinese wei/coplas, Japanese grammatical role
markers, a few English be/behavior words, and one split Thai form of "be".
Only those readable surface cues get small negative estimates; other tokens
get zero. This is not a general semantic parser.
"""

READS = ()

CHINESE_WEI = {"为", "為"}
CHINESE_BEING = {"认为", "成为", "都是", "真是"}
JAPANESE_ROLE_WORDS = {"ことを", "として", "のために", "にして"}
ENGLISH_BE_WORDS = {
    " behavior", " behave", " becomes", " constitute", " behalf", "toBe",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in CHINESE_WEI:
        return None, -5.1
    if token in CHINESE_BEING:
        return None, -1.6
    if token.endswith("が"):
        return None, -1.1
    if token in JAPANESE_ROLE_WORDS:
        return None, -0.9
    if token in ENGLISH_BE_WORDS:
        return None, -0.8
    # The two pieces "เป" + "็น" spell the Thai copula "เป็น".
    if (token == "็น" and len(prefix) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2]
            and prefix.token_strings[-2] == "เป"):
        return None, -0.75
    return None, 0.0

programs.sol:
"""Predict short li-like spelling fragments, not a topic or every word with li.

Latin li/cli and space-prefixed Cyrillic ли are strongest. Short extensions
and several related script forms get smaller responses; most longer words
get zero. HTML list-item tags strengthen li, short g+li junctions weaken it,
and an attached -ly ending is weaker than a short independent fragment.
Small, idiosyncratic responses to other words are deliberately left out.
"""
READS = ()


def spelling_value(token):
    boundary = token[:1].isspace()
    text = token.strip().lstrip('_./-')
    word = text.lower()
    if word in ('li', 'cli'):
        if word == 'cli':
            return 3.2
        return 2.7 if boundary and text != word else 3.5
    if word == 'ли':
        return 5.35 if boundary else 2.35
    if word.endswith('li') and len(word) == 3:
        onset = word[0]
        if onset == 'e':
            return 1.75 if boundary else 3.4
        if onset == 'a':
            return 3.3 if boundary else 2.4
        if onset == 'u':
            return 1.4
        if onset == 'g':
            return 0.4 if boundary else 1.1
        return 2.4
    if word == 'lı':
        return 2.2
    if word == 'لي':
        return 1.45 if boundary else 1.2
    if text in ('리', 'リ'):
        return 1.6 if boundary else 0.5
    if word.endswith('ли') and len(word) == 3:
        if word == 'али':
            return 1.65
        if word == 'ели':
            return 1.35
        if word == 'или':
            return 0.25 if boundary else 1.1
        return 0.85
    if word == 'лиц':
        return 1.7 if boundary else 1.0
    if len(word) == 3 and word.startswith('ли'):
        return 0.55
    # Common library and utility-file abbreviations.
    if word.endswith('lib') and len(word) <= 6:
        return 1.4 if token.lstrip().startswith(('/', '_', '.')) else 1.1
    if word == 'utils':
        return 0.85
    if word == 'ly':
        return 1.4 if boundary else 0.45
    if len(word) == 3 and word.endswith('ly'):
        return 0.55
    if word == 'ley':
        return 0.35
    if len(word) == 3 and word.startswith('li'):
        if word[-1] in 'gkf':
            return 0.35
        if word == 'lie' and boundary:
            return 0.3
        return 0.9
    if word.startswith(('liqu', 'liab', 'lithium')):
        return 1.1
    if word.startswith('licens'):
        return 0.4
    if word in ('alias', 'alien'):
        return 1.4 if word == 'alias' else 0.85
    if len(word) == 4 and 'li' in word:
        if word in ('like', 'life', 'live', 'line', 'link', 'list', 'lich'):
            return 0.0
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = spelling_value(token)
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2]
    # List-item tags are an especially strong use of the separate fragment li.
    if token == 'li' and previous.endswith(('<', '</')):
        value = 4.9
    # Short g-ending fragments form a g+li spelling junction.
    elif token == 'li':
        fragment = previous.strip().lower()
        if len(fragment) <= 3 and fragment.endswith('g'):
            if len(fragment) == 1 or fragment[-2] in 'aeiou':
                value = 1.3
    # An attached -ly ending is weak; a separate short spelling is stronger.
    elif token == 'ly':
        letters = previous.strip()
        if previous[:1].isspace() and len(letters) >= 3:
            value = 0.1
        elif len(letters) <= 2:
            value = 1.0
        else:
            value = 0.6
    return None, float(value)

programs.luna:
"""Predict positive activity on words about research, measurement, and information."""

READS = ()

# A named semantic family: finding, recording, and interpreting information.
RESEARCH_ROOTS = (
    "analys", "observ", "measur", "research", "stud", "experiment",
    "data", "dataset", "evidenc", "result", "sample", "statistic",
    "estimate", "sensor", "microscop", "detect", "identif", "assess",
    "calculat", "analyt", "finding", "survey", "track", "chronolog",
)

# Chinese equivalents of common research / information words.
RESEARCH_WORDS = frozenset((
    "数据", "数据分析", "分析", "研究", "观察", "测量", "调查", "样本",
    "证据", "结果", "统计", "估计", "检测", "识别", "传感器", "显微镜",
))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, word = carry if carry is not None else (doc, "")
    if doc != old_doc:
        word = ""

    # Keep the current alphabetic word across tokenizer pieces.
    for ch in prefix.token_strings[-1].casefold():
        if ch.isalpha():
            word += ch
        else:
            word = ""

    active = word in RESEARCH_WORDS
    if not active:
        for root in RESEARCH_ROOTS:
            if word.startswith(root) and len(word) >= min(5, len(root)):
                active = True
                break
    return (doc, word), (0.53 if active else 0.003)

programs.sol:
"""Recognize words and fragments continuing a form of 'do'.

Emphatic verbs, indefinite objects and performance words get large positive
values; subjects, determiners and negation do not. There is a smaller trace
one token later. Related weaker patterns follow go, no, short o-ending
fragments and perform. Token-specific background variation is not modeled.
The two-token memory resets at document boundaries.
"""
READS = ()

DO = {'do', 'did', 'does', 'doing', 'done'}
SUBJECTS = {'i', 'you', 'he', 'she', 'we', 'they'}
DETERMINERS = {'a', 'an', 'the', 'my', 'your', 'his', 'her', 'its', 'our', 'their'}
INDEFINITES = {
    'something', 'anything', 'nothing', 'everything', 'someone', 'anyone',
    'everyone', 'somebody', 'anybody', 'everybody', 'whatever',
}
EMPHATIC_CONTINUATIONS = {'know', 'think', 'just', 'exactly', 'really', 'only'}
VERBS = {
    'work', 'get', 'make', 'take', 'see', 'need', 'like', 'say', 'give',
    'find', 'seem', 'appear', 'happen', 'mean', 'believe', 'remember',
    'understand', 'want', 'hope', 'feel',
}
ACTIONS_AND_TASKS = {
    'be', 'exist', 'look', 'offer', 'control', 'use', 'read', 'suggest',
    'help', 'try', 'start', 'come', 'call', 'write', 'learn', 'act', 'run',
    'things', 'stuff', 'research', 'exercise', 'homework', 'calculation',
}
QUANTITY = {'all', 'both', 'any', 'more', 'much', 'little', 'enough', 'less'}
QUALITY = {
    'better', 'well', 'best', 'good', 'great', 'worse', 'bad', 'badly', 'poorly',
}


def continuation(word, token):
    if word in SUBJECTS | {'not', "n't", 'never'}:
        return -0.07
    if word in DETERMINERS:
        return 0.02
    if word in {'better', 'well'}:
        return 2.6
    if word in EMPHATIC_CONTINUATIONS:
        return 2.0
    if word in QUALITY | {'have'}:
        return 1.65
    if word in VERBS:
        return 1.4
    if word in INDEFINITES | {'what', 'when', 'one'}:
        return 0.95
    if (word in ACTIONS_AND_TASKS | QUANTITY
            | {'with', 'to', 'for', 'on', 'very', 'almost'}):
        return 0.8
    if word in {'this', 'that', 'these', 'those'}:
        return 0.3
    if word in {'it', 'so', 'is', 'some'}:
        return 0.1
    if word in DO:
        return -0.05
    if word == '|' or (word[:1] in '._-' and any(c.isalpha() for c in word)):
        return 1.2
    if word.isalpha():
        if not token[:1].isspace():
            return 0.65
        return 0.08 if token.strip()[:1].isupper() else 0.32
    return 0.15 if word == ',' else 0.02


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = carry[1:] if carry and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.09 if word in INDEFINITES else 0.004
    if previous in DO:
        value = continuation(word, token) * (0.3 if previous == 'done' else 1.0)
    elif previous in {'go', 'goes', 'went'}:
        value = 0.22 if word.isalpha() or word.startswith('.') else 0.02
        if word in {'to', 'into', 'through', 'in', 'at', 'of', 'from'}:
            value = 0.02
        elif word in {'on', 'back', 'away', 'test'}:
            value = 0.45
    elif previous == 'no':
        value = 0.1 if word.isalpha() else 0.025
        if word == 'one':
            value = 0.95
        elif word in QUALITY | QUANTITY:
            value = 1.2 if word == 'better' else 0.8
        elif word.startswith('-'):
            value = 0.5
    elif (previous.isascii() and previous.isalpha()
          and 1 < len(previous) <= 3 and previous.endswith('o')
          and previous not in {'to', 'so', 'too', 'two', 'who'}):
        value = 0.15
    if before in DO:
        modified_quality = (
            word in QUALITY and previous in {'no', 'much', 'even', 'very'}
        )
        trace = 0.5 if modified_quality else 0.15
        value += trace * max(0.0, continuation(word, token))
    if (previous in {'perform', 'performs', 'performed', 'performing'}
            and word in QUALITY):
        value = 1.2
    return (doc, word.strip('._/-'), previous), float(value)

programs.haiku:
"""Activation of layers.0.mlp.down_proj:4348 as a word-after-"do" detector.

The component writes into the residual stream mainly when the current word follows
an auxiliary or main-verb "do" (do / does / did / doing / done): "I do [think]",
"does [just] that", "do [anything]", "doing [great]", and, more weakly, after "go"
("go [test]", "go [on] sale"), and "no [one]" (the strongest case). It is near zero
on ordinary text. Its prediction is a fixed strength per context, not a fit to data.
"""

READS = ()

DO_FORMS = {"do", "does", "did", "doing", "done"}
# Words right after "do" that do not make it a verb-plus-complement construction:
# "do not", "do you", "did it", "do the" ...
NOT_AFTER_DO = {"not", "n't", "you", "i", "we", "they", "he", "she", "it", "the", "a",
                "is", "in", "so", "this", "my", "your", "sure", "be", ",", ".", "?", "!", ":", ""}
# Indefinite pronouns that complete "do anything", "no one", "nothing to do with"...
ANY_WORDS = {"anything", "anybody", "anyone", "nothing", "something", "everything"}


def step(carry, prefix, upstream):
    t = prefix.position
    cur = prefix.token_strings[t].strip().lower()
    same_doc = t > 0 and prefix.document_ids[t - 1] == prefix.document_ids[t]
    prev = prefix.token_strings[t - 1].strip().lower() if same_doc else ""
    if prev in DO_FORMS:
        if cur in NOT_AFTER_DO:
            value = 0.0
        elif cur in ANY_WORDS:
            value = 0.7
        else:
            value = 0.3
    elif prev == "no":
        value = 0.9 if cur == "one" else 0.07
    elif prev == "go":
        value = 0.2
    elif cur in ANY_WORDS:
        value = 0.15
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Dream vocabulary gives a large negative pulse; related ideas are weaker.

This is a lexical approximation, not a detector of whether someone is
actually dreaming. It also recognizes dream-word endings and 'dream of'
complements, and smaller positive pulses for identifying and labeling.
It retains the last token and its dream pulse, resetting at document
boundaries. It checks completed Unicode characters and the spelling
fragment 'ream'; it otherwise leaves unlisted vocabulary at zero.
"""
READS = ()

DREAMS = {
    'dream': -5.8, 'dreams': -5.2, 'dreaming': -4.9, 'dreamed': -4.5,
    '梦': -7.1, '夢': -6.3, '梦想': -4.5, '的梦想': -3.9,
    '梦境': -4.0, '梦见': -3.9, '梦幻': -3.3, '中国梦': -4.2,
    '꿈': -3.8, '몽': -1.8, 'rê': -2.8, 'rêve': -3.5, 'mơ': -2.1,
}
ENDINGS = {'ing': .88, 's': .86, 'ed': .5, 'er': .58,
           'ers': .58, 't': .35, 'y': .3}


def related_word(word):
    if word in {'nightmare', 'nightmares'}:
        return -2.1
    if word in {'vision', 'visions', 'visionary', 'aspiration', 'aspirations'}:
        return -1.0
    if word in {'fantasy', 'fantasies', 'consciousness', 'subconscious',
                'angel', 'ecstasy', '幻想', '理想', '理想的', '奋斗', '红楼梦'}:
        return -.6
    if word in {'awake', 'asleep', 'waking', 'ambitions', '鬼', '枕', '醒'}:
        return -.8
    if word in {'doll', 'dolls', '魂', '幻', '奋斗目标', '理想信念'}:
        return -1.3
    if word in {'imagine', 'imagined', 'imagination', 'goal', 'goals',
                'desire', 'desired', 'desires', 'sleep', 'sleeping',
                'ambition', 'aspir', '睡', '眠', '睡眠'}:
        return -.3
    if word == 'pillow':
        return -.6
    if word == 'fantas':
        return -1.1
    if word in {'identify', 'identifying', 'identifies', 'labels', 'labeling'}:
        return .75
    if word in {'label', 'identified', 'identification'}:
        return .45
    if word in {'labeled', 'labelled', 'ident'}:
        return .25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0, False)
    _, previous, pulse, spaced = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    space = bool(token[:1].isspace())
    fragmented = '\ufffd' in token
    if fragmented:
        word = prefix.text_prefixes[-1][-1:]
        if word not in {'梦', '夢', '꿈'}:
            word = ''
    dream_pulse = DREAMS.get(word, 0.0)
    value = dream_pulse
    if dream_pulse:
        if word == 'dream' and not space:
            value = -5.3 if token[:1].isupper() else -4.6
        if fragmented and word == '꿈':
            value = -3.2
        dream_pulse = value
    elif pulse and not space and word in ENDINGS:
        coefficient = .72 if word == 'ing' and not spaced else ENDINGS[word]
        value = dream_pulse = pulse * coefficient
    elif pulse and space and word in {'of', 'about', 'to'}:
        value = pulse * {'of': .62, 'about': .47, 'to': .17}[word]
    elif previous in {'梦', '夢'} and word in {'里', '到', '想', '幻'}:
        value = -2.0
    elif previous == 'rê' and word in {'ve', 'ves', 'ver'}:
        value = -1.8
    elif word == 'agine':
        value = -.63
    elif word == 'ream':
        value = -5.0 if previous == 'd' else -1.7
    elif previous == 'ident' and word in {'ify', 'ifying', 'ification'}:
        value = .85
    elif previous in {'lab', 'label'} and word in {'elling', 'ing', 's'}:
        value = .8
    elif previous == 'doll' and word == 's':
        value = -1.1
    else:
        value = related_word(word)
        if not space and token[:1].islower() and word.isascii():
            value *= .3
    return (doc, word, dream_pulse, space), float(value)

"""Lexical signals of reaching an endpoint, strongest in Chinese.

Standalone 到 ('reach/to') and 至 ('up to') dominate. Date ranges retain
most of 至's response. Compounds weaken it: literal arrival is stronger
than seeing, finding or receiving. A few translations respond more weakly.
Split UTF-8 characters and Thai/Indonesian word fragments are reassembled
when needed. Other tokens get zero; small background responses are omitted.
"""
READS = ()

ARRIVAL = {
    '来到', '回到', '走到', '跑到', '赶到', '落到', '降到',
    '带到', '送到', '接到', '等到', '再到', '一直到',
}
ACQUISITION = {'收到', '拿到', '买到', '吃到', '想到', '起到'}
WEAK_RESULTS = {
    '得到', '找到', '受到', '遇到', '看不到', '找不到',
    '做不到', '得不到',
}
TRANSLATIONS = {
    'onto': 0.45, 'unto': 0.28, 'until': 0.14, 'till': 0.18,
    'до': 0.37, 'إلى': 0.42, 'الى': 0.60,
    'đến': 0.68, 'tới': 0.54, 'hasta': 0.19, 'jusqu': 0.27,
}


def lexical(word):
    if word == '至':
        return 3.72
    if word.endswith('至') and word[-2:-1] in {'日', '月', '年'}:
        return 3.12
    if '至' in word:
        if word == '至上':
            return 2.65
        if word in {'至于', '至於'}:
            return 1.70
        if word.startswith('至少'):
            return 0.26
        if word.startswith('甚至'):
            return 1.05 / len(word)
        if word.startswith('至关') or word == '至尊':
            return 1.75 / len(word)
        if word == '以至于':
            return 0.68
        return 1.40 if len(word) == 2 else 1.20
    if word == '到':
        return 1.75
    if word == '到了':
        return 1.44
    if word == '不到':
        return 1.03
    if '到' in word:
        if word.startswith(('到现在', '到最后', '到这里')):
            return 1.27
        if word == '到底是':
            return 0.0
        stem = word[:-1] if word.endswith('了') else word
        aspect = 0.75 if stem != word else 1.0
        if stem in ARRIVAL:
            return 1.05 * aspect
        if stem in ACQUISITION:
            return 0.88 * aspect
        if stem in WEAK_RESULTS:
            return 0.28 * aspect
        if stem in {'达到', '達到', '到底', '到位'}:
            return 0.43 * aspect
        if stem == '到处':
            return 0.26
        return 0.55 * aspect
    if word == '致':
        return 0.67
    if word in {'导致', '導致'}:
        return 0.29
    if word in {'迄', '迄今'}:
        return 0.85
    if word.startswith('まで'):
        return 0.32
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip()
    # Reassemble a split UTF-8 endpoint character only when necessary.
    recent_docs = prefix.document_ids[-3:]
    one_doc = all(d == recent_docs[-1] for d in recent_docs)
    if '\ufffd' in word and one_doc:
        tail = prefix.text_prefixes[-1][-1:]
        word = tail if tail in {'到', '至', '致', '迄'} else word
    value = lexical(word)
    if word == 'ingga':
        recent = zip(prefix.token_strings[-3:], recent_docs)
        tail = ''.join(s for s, d in recent
                       if d == recent_docs[-1]).lower()
        # hingga means 'until'; sehingga is its result/consequence compound.
        value = 0.25 if tail.endswith('sehingga') else 0.52
    if word == 'ึง' and len(prefix.token_strings) > 1:
        same_doc = prefix.document_ids[-1] == prefix.document_ids[-2]
        if same_doc and prefix.token_strings[-2] == 'ถ':
            value = 0.40  # Thai ถึง: reach / until.
    if word in TRANSLATIONS:
        value = TRANSLATIONS[word]
        if not raw[:1].isspace() and word not in {'until', 'till'}:
            value *= 0.33
    return None, float(value)

programs.luna:
"""Approximate the rare endpoint/reaching-word feature of this MLP component.

The strongest readable cue is Chinese 到 or 至; the same feature also appears
on a few words meaning toward, up to, or until in other scripts. Most tokens
do not match and receive zero.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()

    if token == "到":
        value = 1.75
    elif token == "至":
        value = 3.55
    elif "到" in token or "至" in token:
        value = 0.72
    elif "致" in token:
        value = 0.62
    elif any(word in token for word in ("إلى", "onto", "đến", "まで")):
        value = 0.48
    elif token.strip() == "до":
        value = 0.48
    elif token in ("ingga", "ึง"):
        value = 0.48
    else:
        value = 0.0

    return carry, value
